export default "\\n        import os\\n        from pathlib import Path as _Path\\n\\n        original_cwd = _Path.cwd()\\n        os.chdir(tmp_path)\\n        try:\\n            with (\\n                patch(\\\"lfx.cli.pull.load_sdk\\\", return_value=sdk),\\n                patch(\\\"lfx.config.resolve_environment\\\", return_value=cfg),\\n            ):\\n                pull_command(\\n                    env=None,\\n                    output_dir=None,\\n                    flow_id=None,\\n                    project=None,\\n                    project_id=None,\\n                    environments_file=None,\\n                    target=_BASE_URL,\\n                    api_key=_API_KEY,\\n                    strip_secrets=False,\\n                    indent=2,\\n                )\\n            flows_dir = tmp_path / \\\"flows\\\"\\n            assert flows_dir.exists()\\n        finally:\\n            os.chdir(original_cwd)\\n\\n    def test_creates_output_dir_if_not_exists(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock(flows=[flow])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        new_dir = tmp_path / \\\"brand_new_dir\\\"\\n        assert not new_dir.exists()\\n        _run_pull(tmp_path=tmp_path, output_dir=str(new_dir), sdk_mock=sdk)\\n        assert new_dir.exists()\\n\\n    def test_uses_custom_dir_when_specified(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock(flows=[flow])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        custom_dir = tmp_path / \\\"my_custom_flows\\\"\\n        _run_pull(tmp_path=tmp_path, output_dir=str(custom_dir), sdk_mock=sdk)\\n        assert custom_dir.exists()\\n        json_files = list(custom_dir.glob(\\\"*.json\\\"))\\n        assert len(json_files) == 1\\n\\n    def test_creates_nested_output_dir(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock(flows=[flow])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        nested_dir = tmp_path / \\\"a\\\" / \\\"b\\\" / \\\"c\\\"\\n        _run_pull(tmp_path=tmp_path, output_dir=str(nested_dir), sdk_mock=sdk)\\n        assert nested_dir.exists()\\n\\n    def test_uses_existing_output_dir(self, tmp_path: Path):\\n        flow = _fake_flow_obj()\\n        client = _make_client_mock(flows=[flow])\\n        sdk = _make_sdk_mock(client_mock=client)\\n        existing_dir = tmp_path / \\\"existing\\\"\\n        existing_dir.mkdir()\\n        _run_pull(tmp_path=tmp_path, output_dir=str(existing_dir), sdk_mock=sdk)\\n        json_files = list(existing_dir.glob(\\\"*.json\\\"))\\n        assert len(json_files) == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# _render_results\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRenderResults:\\n    def test_does_not_crash_with_mixed_statuses(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult, _render_results\\n\\n        results = [\\n            PullResult(flow_id=_FLOW_ID, flow_name=\\\"A\\\", path=tmp_path / \\\"a.json\\\", status=\\\"created\\\"),\\n            PullResult(flow_id=_FLOW_ID_2, flow_name=\\\"B\\\", path=tmp_path / \\\"b.json\\\", status=\\\"updated\\\"),\\n            PullResult(\\n                flow_id=UUID(\\\"cccccccc-0000-0000-0000-000000000001\\\"),\\n                flow_name=\\\"C\\\",\\n                path=tmp_path / \\\"c.json\\\",\\n                status=\\\"unchanged\\\",\\n            ),\\n            PullResult(\\n                flow_id=UUID(\\\"dddddddd-0000-0000-0000-000000000001\\\"),\\n                flow_name=\\\"D\\\",\\n                path=tmp_path / \\\"d.json\\\",\\n                status=\\\"error\\\",\\n                error=\\\"something went wrong\\\",\\n            ),\\n        ]\\n        # Should not raise\\n        _render_results(results)\\n\\n    def test_does_not_crash_with_empty_results(self):\\n        from lfx.cli.pull import _render_results\\n\\n        _render_results([])\\n\\n    def test_does_not_crash_with_all_unchanged(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult, _render_results\\n\\n        results = [\\n            PullResult(flow_id=_FLOW_ID, flow_name=\\\"A\\\", path=tmp_path / \\\"a.json\\\", status=\\\"unchanged\\\"),\\n            PullResult(flow_id=_FLOW_ID_2, flow_name=\\\"B\\\", path=tmp_path / \\\"b.json\\\", status=\\\"unchanged\\\"),\\n        ]\\n        _render_results(results)\\n\\n    def test_does_not_crash_with_all_errors(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult, _render_results\\n\\n        results = [\\n            PullResult(\\n                flow_id=_FLOW_ID,\\n                flow_name=\\\"A\\\",\\n                path=tmp_path / \\\"a.json\\\",\\n                status=\\\"error\\\",\\n                error=\\\"network error\\\",\\n            ),\\n        ]\\n        _render_results(results)\\n\\n    def test_does_not_crash_with_single_created(self, tmp_path: Path):\\n        from lfx.cli.pull import PullResult, _render_results\\n\\n        results = [\\n            PullResult(flow_id=_FLOW_ID, flow_name=\\\"My Flow\\\", path=tmp_path / \\\"my_flow.json\\\", status=\\\"created\\\"),\\n        ]\\n        _render_results(results)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_push_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"53cad2aba32c914c43b22dda2520e37cdf9ad7fbd9129c4ddfbc04b1d865b248\",\"content\":\"\\\"\\\"\\\"Unit tests for lfx push -- push_command and helpers.\\n\\nAll tests run entirely in-process; no real Langflow instance or SDK required.\\nThe SDK module is replaced wholesale with MagicMock so only the push logic\\n(file loading, upsert routing, dry-run, project resolution, result rendering)\\nis under test.\\n\\\"\\\"\\\"\\n# pragma: allowlist secret -- all credentials in this file are fake test data\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import MagicMock, patch\\nfrom uuid import UUID\\n\\nimport pytest\\nimport typer\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n# ---------------------------------------------------------------------------\\n# Shared constants\\n# ---------------------------------------------------------------------------\\n\\n_BASE_URL = \\\"http://langflow.test\\\"\\n_API_KEY = \\\"test-key\\\"  # pragma: allowlist secret\\n_FLOW_ID = UUID(\\\"aaaaaaaa-0000-0000-0000-000000000001\\\")\\n_FLOW_ID_2 = UUID(\\\"aaaaaaaa-0000-0000-0000-000000000002\\\")\\n_PROJECT_ID = UUID(\\\"bbbbbbbb-0000-0000-0000-000000000001\\\")\\n\\n_FLOW_DICT: dict = {\\n    \\\"id\\\": str(_FLOW_ID),\\n    \\\"name\\\": \\\"My Test Flow\\\",\\n    \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n}\\n\\n_FLOW_DICT_2: dict = {\\n    \\\"id\\\": str(_FLOW_ID_2),\\n    \\\"name\\\": \\\"Second Flow\\\",\\n    \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Fake exception class \u2014 avoids importing langflow_sdk in isolation mode\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _FakeLangflowHTTPError(Exception):\\n    \\\"\\\"\\\"Stand-in for langflow_sdk.LangflowHTTPError in unit tests.\\\"\\\"\\\"\\n\\n    def __init__(self, status_code: int, detail: str) -> None:\\n        self.status_code = status_code\\n        super().__init__(detail)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Test helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _write_flow(tmp_path: Path, name: str, flow: dict | None = None) -> Path:\\n    p = tmp_path / name\\n    p.parent.mkdir(parents=True, exist_ok=True)\\n    p.write_text(json.dumps(flow if flow is not None else _FLOW_DICT), encoding=\\\"utf-8\\\")\\n    return p\\n\\n\\ndef _fake_project(name: str = \\\"My Project\\\", project_id: UUID = _PROJECT_ID) -> MagicMock:\\n    \\\"\\\"\\\"Return a MagicMock that looks like a langflow_sdk.models.Project.\\\"\\\"\\\"\\n    proj = MagicMock()\\n    proj.name = name\\n    proj.id = project_id\\n    return proj\\n\\n\\ndef _fake_flow(flow_id: UUID = _FLOW_ID, name: str = \\\"My Test Flow\\\") -> MagicMock:\\n    \\\"\\\"\\\"Return a MagicMock that looks like a langflow_sdk.models.Flow.\\\"\\\"\\\"\\n    flow = MagicMock()\\n    flow.id = flow_id\\n    flow.name = name\\n    return flow\\n\\n\\ndef _make_client_mock(*, create: bool = True) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock SDK client whose upsert_flow returns (flow, created).\\\"\\\"\\\"\\n    client = MagicMock()\\n    client.upsert_flow.return_value = (_fake_flow(), create)\\n    client.list_projects.return_value = []\\n    client.create_project.return_value = _fake_project()\\n    return client\\n\\n\\ndef _make_sdk_mock(client_mock: MagicMock | None = None) -> MagicMock:\\n    \\\"\\\"\\\"Return a mock langflow_sdk module wired to client_mock.\\n\\n    SDK exception and model types are replaced with lightweight fakes so\\n    the test file has zero imports from langflow_sdk.\\n    \\\"\\\"\\\"\\n    if client_mock is None:\\n        client_mock = _make_client_mock()\\n\\n    sdk = MagicMock()\\n    sdk.Client.return_value = client_mock\\n    sdk.LangflowHTTPError = _FakeLangflowHTTPError\\n    # FlowCreate / ProjectCreate stay as MagicMock callables \u2014 push.py calls\\n    # them as constructors and passes the result to client.upsert_flow /\\n    # client.create_project.  We check the constructor call kwargs in tests.\\n    return sdk\\n\\n\\ndef _run_push(\\n    flow_paths: list[str],\\n    *,\\n    dir_path: str | None = None,\\n    project: str | None = None,\\n    project_id: str | None = None,\\n    environments_file: str | None = None,\\n    env: str | None = None,\\n    dry_run: bool = False,\\n    normalize: bool = False,\\n    strip_secrets: bool = False,\\n    sdk_mock: MagicMock | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Invoke push_command with mocked SDK, using --target for inline env resolution.\\\"\\\"\\\"\\n    from lfx.cli.push import push_command\\n\\n    mock = sdk_mock if sdk_mock is not None else _make_sdk_mock()\\n    with patch(\\\"lfx.cli.push.load_sdk\\\", return_value=mock):\\n        push_command(\\n            flow_paths=flow_paths,\\n            env=env,\\n            dir_path=dir_path,\\n            project=project,\\n            project_id=project_id,\\n            environments_file=environments_file,\\n            target=_BASE_URL,\\n            api_key=_API_KEY,\\n            dry_run=dry_run,\\n            normalize=normalize,\\n            strip_secrets=strip_secrets,\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# PushResult\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPushResult:\\n    def test_created_is_ok(self, tmp_path):\\n        from lfx.cli.push import PushResult\\n\\n        r = PushResult(path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID, flow_name=\\\"F\\\", status=\\\"created\\\")\\n        assert r.ok is True\\n\\n    def test_updated_is_ok(self, tmp_path):\\n        from lfx.cli.push import PushResult\\n\\n        r = PushResult(path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID, flow_name=\\\"F\\\", status=\\\"updated\\\")\\n        assert r.ok is True\\n\\n    def test_dry_run_is_ok(self, tmp_path):\\n        from lfx.cli.push import PushResult\\n\\n        r = PushResult(path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID, flow_name=\\\"F\\\", status=\\\"dry-run\\\")\\n        assert r.ok is True\\n\\n    def test_error_is_not_ok(self, tmp_path):\\n        from lfx.cli.push import PushResult\\n\\n        r = PushResult(path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID, flow_name=\\\"F\\\", status=\\\"error\\\", error=\\\"timeout\\\")\\n        assert r.ok is False\\n\\n    def test_error_message_stored(self, tmp_path):\\n        from lfx.cli.push import PushResult\\n\\n        r = PushResult(path=tmp_path / \\\"f.json\\\", flow_id=_FLOW_ID, flow_name=\\\"F\\\", status=\\\"error\\\", error=\\\"some error\\\")\\n        assert r.error == \\\"some error\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# _load_flow_file\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLoadFlowFile:\\n    def test_valid_json_returns_dict(self, tmp_path):\\n        from lfx.cli.push import _load_flow_file\\n\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        result = _load_flow_file(p)\\n        assert result[\\\"id\\\"] == str(_FLOW_ID)\\n        assert result[\\\"name\\\"] == \\\"My Test Flow\\\"\\n\\n    def test_invalid_json_raises_exit(self, tmp_path):\\n        from lfx.cli.push import _load_flow_file\\n\\n        p = tmp_path / \\\"bad.json\\\"\\n        p.write_text(\\\"not valid json\\\", encoding=\\\"utf-8\\\")\\n        with pytest.raises(typer.Exit):\\n            _load_flow_file(p)\\n\\n    def test_missing_file_raises_exit(self, tmp_path):\\n        from lfx.cli.push import _load_flow_file\\n\\n        with pytest.raises(typer.Exit):\\n            _load_flow_file(tmp_path / \\\"nonexistent.json\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# _extract_flow_id\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestExtractFlowId:\\n    def test_valid_uuid_returned(self, tmp_path):\\n        from lfx.cli.push import _extract_flow_id\\n\\n        path = tmp_path / \\\"f.json\\\"\\n        result = _extract_flow_id({\\\"id\\\": str(_FLOW_ID)}, path)\\n        assert result == _FLOW_ID\\n\\n    def test_missing_id_raises_exit(self, tmp_path):\\n        from lfx.cli.push import _extract_flow_id\\n\\n        with pytest.raises(typer.Exit):\\n            _extract_flow_id({}, tmp_path / \\\"f.json\\\")\\n\\n    def test_null_id_raises_exit(self, tmp_path):\\n        from lfx.cli.push import _extract_flow_id\\n\\n        with pytest.raises(typer.Exit):\\n            _extract_flow_id({\\\"id\\\": None}, tmp_path / \\\"f.json\\\")\\n\\n    def test_invalid_uuid_raises_exit(self, tmp_path):\\n        from lfx.cli.push import _extract_flow_id\\n\\n        with pytest.raises(typer.Exit):\\n            _extract_flow_id({\\\"id\\\": \\\"not-a-uuid\\\"}, tmp_path / \\\"f.json\\\")\\n\\n    def test_uuid_type_returned(self, tmp_path):\\n        from lfx.cli.push import _extract_flow_id\\n\\n        path = tmp_path / \\\"f.json\\\"\\n        result = _extract_flow_id({\\\"id\\\": \\\"aaaaaaaa-0000-0000-0000-000000000001\\\"}, path)\\n        assert isinstance(result, UUID)\\n\\n\\n# ---------------------------------------------------------------------------\\n# _collect_flow_files\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestCollectFlowFiles:\\n    def test_single_path_returned(self, tmp_path):\\n        from lfx.cli.push import _collect_flow_files\\n\\n        p = _write_flow(tmp_path, \\\"a.json\\\")\\n        result = _collect_flow_files([str(p)], None)\\n        assert result == [p]\\n\\n    def test_multiple_paths_returned(self, tmp_path):\\n        from lfx.cli.push import _collect_flow_files\\n\\n        p1 = _write_flow(tmp_path, \\\"a.json\\\")\\n        p2 = _write_flow(tmp_path, \\\"b.json\\\", _FLOW_DICT_2)\\n        result = _collect_flow_files([str(p1), str(p2)], None)\\n        assert set(result) == {p1, p2}\\n\\n    def test_dir_finds_all_json(self, tmp_path):\\n        from lfx.cli.push import _collect_flow_files\\n\\n        d = tmp_path / \\\"flows\\\"\\n        d.mkdir()\\n        (d / \\\"a.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        (d / \\\"b.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        (d / \\\"notes.txt\\\").write_text(\\\"ignore\\\", encoding=\\\"utf-8\\\")\\n        result = _collect_flow_files([], str(d))\\n        assert len(result) == 2\\n        assert all(p.suffix == \\\".json\\\" for p in result)\\n\\n    def test_dir_and_paths_combined(self, tmp_path):\\n        from lfx.cli.push import _collect_flow_files\\n\\n        d = tmp_path / \\\"flows\\\"\\n        d.mkdir()\\n        dir_flow = d / \\\"dir.json\\\"\\n        dir_flow.write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")\\n        extra = _write_flow(tmp_path, \\\"extra.json\\\")\\n        result = _collect_flow_files([str(extra)], str(d))\\n        assert dir_flow in result\\n        assert extra in result\\n\\n    def test_missing_path_raises_exit(self, tmp_path):\\n        from lfx.cli.push import _collect_flow_files\\n\\n        with pytest.raises(typer.Exit):\\n            _collect_flow_files([str(tmp_path / \\\"missing.json\\\")], None)\\n\\n    def test_dir_is_file_raises_exit(self, tmp_path):\\n        from lfx.cli.push import _collect_flow_files\\n\\n        p = _write_flow(tmp_path, \\\"a.json\\\")\\n        with pytest.raises(typer.Exit):\\n            _collect_flow_files([], str(p))  # file passed as dir\\n\\n    def test_empty_dir_returns_empty_list(self, tmp_path):\\n        from lfx.cli.push import _collect_flow_files\\n\\n        d = tmp_path / \\\"empty\\\"\\n        d.mkdir()\\n        result = _collect_flow_files([], str(d))\\n        assert result == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# _upsert_single\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestUpsertSingle:\\n    def _flow_create_mock(self) -> MagicMock:\\n        return MagicMock()\\n\\n    def test_dry_run_returns_dry_run_status(self, tmp_path):\\n        from lfx.cli.push import _upsert_single\\n\\n        client = MagicMock()\\n        sdk = _make_sdk_mock(client)\\n        result = _upsert_single(\\n            client,\\n            sdk,\\n            tmp_path / \\\"f.json\\\",\\n            _FLOW_ID,\\n            self._flow_create_mock(),\\n            dry_run=True,\\n            flow_name=\\\"T\\\",\\n            base_url=\\\"http://test\\\",\\n        )\\n        assert result.status == \\\"dry-run\\\"\\n        assert result.ok is True\\n        client.upsert_flow.assert_not_called()\\n\\n    def test_create_returns_created_status(self, tmp_path):\\n        from lfx.cli.push import _upsert_single\\n\\n        client = _make_client_mock(create=True)\\n        sdk = _make_sdk_mock(client)\\n        result = _upsert_single(\\n            client,\\n            sdk,\\n            tmp_path / \\\"f.json\\\",\\n            _FLOW_ID,\\n            self._flow_create_mock(),\\n            dry_run=False,\\n            flow_name=\\\"T\\\",\\n            base_url=\\\"http://test\\\",\\n        )\\n        assert result.status == \\\"created\\\"\\n        assert result.ok is True\\n\\n    def test_update_returns_updated_status(self, tmp_path):\\n        from lfx.cli.push import _upsert_single\\n\\n        client = _make_client_mock(create=False)\\n        sdk = _make_sdk_mock(client)\\n        result = _upsert_single(\\n            client,\\n            sdk,\\n            tmp_path / \\\"f.json\\\",\\n            _FLOW_ID,\\n            self._flow_create_mock(),\\n            dry_run=False,\\n            flow_name=\\\"T\\\",\\n            base_url=\\\"http://test\\\",\\n        )\\n        assert result.status == \\\"updated\\\"\\n        assert result.ok is True\\n\\n    def test_http_error_returns_error_status(self, tmp_path):\\n        from lfx.cli.push import _upsert_single\\n\\n        client = _make_client_mock()\\n        client.upsert_flow.side_effect = _FakeLangflowHTTPError(500, \\\"server error\\\")\\n        sdk = _make_sdk_mock(client)\\n        result = _upsert_single(\\n            client,\\n            sdk,\\n            tmp_path / \\\"f.json\\\",\\n            _FLOW_ID,\\n            self._flow_create_mock(),\\n            dry_run=False,\\n            flow_name=\\\"T\\\",\\n            base_url=\\\"http://test\\\",\\n        )\\n        assert result.status == \\\"error\\\"\\n        assert result.error is not None\\n        assert result.ok is False\\n\\n    def test_upsert_called_with_correct_flow_id(self, tmp_path):\\n        from lfx.cli.push import _upsert_single\\n\\n        client = _make_client_mock(create=True)\\n        sdk = _make_sdk_mock(client)\\n        fc = self._flow_create_mock()\\n        _upsert_single(\\n            client, sdk, tmp_path / \\\"f.json\\\", _FLOW_ID, fc, dry_run=False, flow_name=\\\"T\\\", base_url=\\\"http://test\\\"\\n        )\\n        client.upsert_flow.assert_called_once_with(_FLOW_ID, fc)\\n\\n\\n# ---------------------------------------------------------------------------\\n# _find_or_create_project\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFindOrCreateProject:\\n    def test_found_project_returns_id(self):\\n        from lfx.cli.push import _find_or_create_project\\n\\n        client = MagicMock()\\n        client.list_projects.return_value = [_fake_project(name=\\\"MyProj\\\")]\\n        sdk = _make_sdk_mock(client)\\n        result = _find_or_create_project(client, sdk, \\\"MyProj\\\", dry_run=False)\\n        assert result == _PROJECT_ID\\n        client.create_project.assert_not_called()\\n\\n    def test_not_found_creates_and_returns_id(self):\\n        from lfx.cli.push import _find_or_create_project\\n\\n        client = MagicMock()\\n        client.list_projects.return_value = []\\n        client.create_project.return_value = _fake_project(name=\\\"NewProj\\\")\\n        sdk = _make_sdk_mock(client)\\n        result = _find_or_create_project(client, sdk, \\\"NewProj\\\", dry_run=False)\\n        assert result == _PROJECT_ID\\n        client.create_project.assert_called_once()\\n\\n    def test_dry_run_returns_none_without_creating(self):\\n        from lfx.cli.push import _find_or_create_project\\n\\n        client = MagicMock()\\n        client.list_projects.return_value = []\\n        sdk = _make_sdk_mock(client)\\n        result = _find_or_create_project(client, sdk, \\\"Ghost\\\", dry_run=True)\\n        assert result is None\\n        client.create_project.assert_not_called()\\n\\n    def test_dry_run_existing_project_returns_id(self):\\n        from lfx.cli.push import _find_or_create_project\\n\\n        client = MagicMock()\\n        client.list_projects.return_value = [_fake_project(name=\\\"Found\\\")]\\n        sdk = _make_sdk_mock(client)\\n        result = _find_or_create_project(client, sdk, \\\"Found\\\", dry_run=True)\\n        assert result == _PROJECT_ID\\n\\n\\n# ---------------------------------------------------------------------------\\n# push_command \u2014 integration (mocked SDK)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestPushCommand:\\n    def test_single_file_create(self, tmp_path):\\n        \\\"\\\"\\\"Single flow JSON \u2192 upsert called once \u2192 created.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(create=True)\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], sdk_mock=sdk)\\n        client.upsert_flow.assert_called_once()\\n        flow_id_arg = client.upsert_flow.call_args[0][0]\\n        assert flow_id_arg == _FLOW_ID\\n\\n    def test_single_file_update(self, tmp_path):\\n        \\\"\\\"\\\"Second push \u2192 update (200).\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(create=False)\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], sdk_mock=sdk)\\n        client.upsert_flow.assert_called_once()\\n\\n    def test_directory_pushes_all_json_files(self, tmp_path):\\n        \\\"\\\"\\\"--dir pushes every *.json in the directory.\\\"\\\"\\\"\\n        d = tmp_path / \\\"flows\\\"\\n        d.mkdir()\\n        (d / \\\"a.json\\\").write_text(json.dumps(_FLOW_DICT), encoding=\\\"utf-8\\\")\\n        (d / \\\"b.json\\\").write_text(json.dumps(_FLOW_DICT_2), encoding=\\\"utf-8\\\")\\n        (d / \\\"readme.txt\\\").write_text(\\\"ignore\\\", encoding=\\\"utf-8\\\")\\n\\n        client = _make_client_mock(create=True)\\n        client.upsert_flow.side_effect = [\\n            (_fake_flow(_FLOW_ID), True),\\n            (_fake_flow(_FLOW_ID_2, \\\"Second Flow\\\"), True),\\n        ]\\n        sdk = _make_sdk_mock(client)\\n        _run_push([], dir_path=str(d), sdk_mock=sdk)\\n        assert client.upsert_flow.call_count == 2\\n\\n    def test_dry_run_makes_no_upsert_calls(self, tmp_path):\\n        \\\"\\\"\\\"Dry-run: upsert_flow is never called.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock()\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], dry_run=True, sdk_mock=sdk)\\n        client.upsert_flow.assert_not_called()\\n\\n    def test_dry_run_creates_client_but_not_upsert(self, tmp_path):\\n        \\\"\\\"\\\"In dry-run mode the SDK Client is constructed (for project lookups).\\n\\n        upsert_flow is never called.\\n        \\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock()\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], dry_run=True, sdk_mock=sdk)\\n        sdk.Client.assert_called_once()\\n        client.upsert_flow.assert_not_called()\\n\\n    def test_no_flow_files_exits(self):\\n        \\\"\\\"\\\"No paths and no --dir \u2192 Exit(1).\\\"\\\"\\\"\\n        with pytest.raises(typer.Exit):\\n            _run_push([])\\n\\n    def test_flow_missing_id_exits(self, tmp_path):\\n        \\\"\\\"\\\"JSON without 'id' field \u2192 Exit(1).\\\"\\\"\\\"\\n        p = tmp_path / \\\"no_id.json\\\"\\n        p.write_text(json.dumps({\\\"name\\\": \\\"Orphan\\\", \\\"data\\\": {}}), encoding=\\\"utf-8\\\")\\n        with pytest.raises(typer.Exit):\\n            _run_push([str(p)])\\n\\n    def test_http_error_exits_with_code_1(self, tmp_path):\\n        \\\"\\\"\\\"HTTP failure on any flow \u2192 Exit(1) after all flows attempted.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock()\\n        client.upsert_flow.side_effect = _FakeLangflowHTTPError(500, \\\"oops\\\")\\n        sdk = _make_sdk_mock(client)\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_push([str(p)], sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_with_project_name_resolves_folder_id(self, tmp_path):\\n        \\\"\\\"\\\"--project triggers lookup; resolved folder_id passed to FlowCreate.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(create=True)\\n        client.list_projects.return_value = [_fake_project(name=\\\"My Proj\\\")]\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], project=\\\"My Proj\\\", sdk_mock=sdk)\\n        client.list_projects.assert_called_once()\\n        fc_kwargs = sdk.FlowCreate.call_args.kwargs\\n        assert fc_kwargs[\\\"folder_id\\\"] == _PROJECT_ID\\n\\n    def test_with_project_name_creates_if_not_found(self, tmp_path):\\n        \\\"\\\"\\\"--project creates the remote project when it doesn't exist.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(create=True)\\n        client.list_projects.return_value = []\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], project=\\\"New Proj\\\", sdk_mock=sdk)\\n        client.create_project.assert_called_once()\\n\\n    def test_with_project_id_skips_lookup(self, tmp_path):\\n        \\\"\\\"\\\"--project-id bypasses list_projects entirely.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(create=True)\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], project_id=str(_PROJECT_ID), sdk_mock=sdk)\\n        client.list_projects.assert_not_called()\\n        fc_kwargs = sdk.FlowCreate.call_args.kwargs\\n        assert fc_kwargs[\\\"folder_id\\\"] == _PROJECT_ID\\n\\n    def test_normalize_calls_sdk_normalize_flow(self, tmp_path):\\n        \\\"\\\"\\\"--normalize invokes sdk.normalize_flow before upsert.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(create=True)\\n        sdk = _make_sdk_mock(client)\\n        sdk.normalize_flow.return_value = _FLOW_DICT\\n        _run_push([str(p)], normalize=True, sdk_mock=sdk)\\n        sdk.normalize_flow.assert_called_once()\\n\\n    def test_no_normalize_skips_sdk_normalize(self, tmp_path):\\n        \\\"\\\"\\\"With normalize=False the SDK normalize_flow is never called.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock(create=True)\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], normalize=False, sdk_mock=sdk)\\n        sdk.normalize_flow.assert_not_called()\\n\\n    def test_partial_error_still_attempts_all_files(self, tmp_path):\\n        \\\"\\\"\\\"An error on one flow does not abort the remaining pushes.\\\"\\\"\\\"\\n        p1 = _write_flow(tmp_path, \\\"ok.json\\\")\\n        p2 = _write_flow(tmp_path, \\\"bad.json\\\", _FLOW_DICT_2)\\n        client = _make_client_mock()\\n        client.upsert_flow.side_effect = [\\n            (_fake_flow(), True),\\n            _FakeLangflowHTTPError(500, \\\"server down\\\"),\\n        ]\\n        sdk = _make_sdk_mock(client)\\n        with pytest.raises(typer.Exit) as exc_info:\\n            _run_push([str(p1), str(p2)], sdk_mock=sdk)\\n        assert exc_info.value.exit_code == 1\\n        assert client.upsert_flow.call_count == 2  # both files were attempted\\n\\n    def test_client_constructed_with_resolved_url_and_key(self, tmp_path):\\n        \\\"\\\"\\\"SDK Client is constructed with the inline URL and API key.\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        client = _make_client_mock()\\n        sdk = _make_sdk_mock(client)\\n        _run_push([str(p)], sdk_mock=sdk)\\n        sdk.Client.assert_called_once_with(base_url=_BASE_URL, api_key=_API_KEY)\\n\\n    def test_environments_file_resolves_url(self, tmp_path):\\n        \\\"\\\"\\\"Environment is resolved from a TOML config file (no --target).\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        env_file = tmp_path / \\\"langflow-environments.toml\\\"\\n        env_file.write_text(\\n            f'[environments.ci]\\\\nurl = \\\"{_BASE_URL}\\\"\\\\n',\\n            encoding=\\\"utf-8\\\",\\n        )\\n        from lfx.cli.push import push_command\\n\\n        client = _make_client_mock(create=True)\\n        sdk = _make_sdk_mock(client)\\n        with patch(\\\"lfx.cli.push.load_sdk\\\", return_value=sdk):\\n            push_command(\\n                flow_paths=[str(p)],\\n                env=\\\"ci\\\",\\n                dir_path=None,\\n                project=None,\\n                project_id=None,\\n                environments_file=str(env_file),\\n                target=None,\\n                api_key=None,\\n                dry_run=False,\\n                normalize=False,\\n                strip_secrets=False,\\n            )\\n        sdk.Client.assert_called_once_with(base_url=_BASE_URL, api_key=None)\\n\\n    def test_missing_environments_file_exits(self, tmp_path):\\n        \\\"\\\"\\\"A non-existent --environments-file \u2192 ConfigError \u2192 Exit(1).\\\"\\\"\\\"\\n        p = _write_flow(tmp_path, \\\"flow.json\\\")\\n        from lfx.cli.push import push_command\\n\\n        sdk = _make_sdk_mock()\\n        with patch(\\\"lfx.cli.push.load_sdk\\\", return_value=sdk), pytest.raises(typer.Exit):\\n            push_command(\\n                flow_paths=[str(p)],\\n                env=\\\"missing\\\",\\n                dir_path=None,\\n                project=None,\\n                project_id=None,\\n                environments_file=str(tmp_path / \\\"missing.yaml\\\"),\\n                target=None,\\n                api_key=None,\\n                dry_run=False,\\n                normalize=False,\\n                strip_secrets=False,\\n            )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_run_command.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"82c58527775efb7de1ea09f5c731be4db37337055e604a8aac4ef6764881ed03\",\"content\":\"\\\"\\\"\\\"Unit tests for the run command functionality.\\\"\\\"\\\"\\n\\nimport contextlib\\nimport json\\nimport tempfile\\nfrom pathlib import Path\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport pytest\\nimport typer\\nfrom lfx.cli.run import run\\n\\n\\nclass TestRunCommand:\\n    \\\"\\\"\\\"Unit tests for run command internal functionality.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def simple_chat_script(self, tmp_path):\\n        \\\"\\\"\\\"Create a simple chat script for testing.\\\"\\\"\\\"\\n        script_content = '''\\\"\\\"\\\"A simple chat flow example for Langflow.\\n\\nThis script demonstrates how to set up a basic conversational flow using Langflow's ChatInput and ChatOutput components.\\n\\nFeatures:\\n- Configures logging to 'langflow.log' at INFO level\\n- Connects ChatInput to ChatOutput\\n- Builds a Graph object for the flow\\n\\nUsage:\\n    python simple_chat.py\\n\\nYou can use this script as a template for building more complex conversational flows in Langflow.\\n\\\"\\\"\\\"\\n\\nfrom pathlib import Path\\n\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.graph import Graph\\nfrom lfx.log.logger import LogConfig\\n\\nlog_config = LogConfig(\\n    log_level=\\\"INFO\\\",\\n    log_file=Path(\\\"langflow.log\\\"),\\n)\\nchat_input = ChatInput()\\nchat_output = ChatOutput().set(input_value=chat_input.message_response)\\n\\ngraph = Graph(chat_input, chat_output, log_config=log_config)\\n'''\\n        script_path = tmp_path / \\\"simple_chat.py\\\"\\n        script_path.write_text(script_content)\\n        return script_path\\n\\n    @pytest.fixture\\n    def invalid_script(self, tmp_path):\\n        \\\"\\\"\\\"Create a script without a graph variable.\\\"\\\"\\\"\\n        script_content = '''\\\"\\\"\\\"Invalid script without graph variable.\\\"\\\"\\\"\\n\\nfrom lfx.components.input_output import ChatInput\\n\\nchat_input = ChatInput()\\n# Missing graph variable\\n'''\\n        script_path = tmp_path / \\\"invalid_script.py\\\"\\n        script_path.write_text(script_content)\\n        return script_path\\n\\n    @pytest.fixture\\n    def syntax_error_script(self, tmp_path):\\n        \\\"\\\"\\\"Create a script with syntax errors.\\\"\\\"\\\"\\n        script_content = '''\\\"\\\"\\\"Script with syntax errors.\\\"\\\"\\\"\\n\\nfrom lfx.components.input_output import ChatInput\\n\\n# Syntax error - missing closing parenthesis\\nchat_input = ChatInput(\\n'''\\n        script_path = tmp_path / \\\"syntax_error.py\\\"\\n        script_path.write_text(script_content)\\n        return script_path\\n\\n    @pytest.fixture\\n    def simple_json_flow(self):\\n        \\\"\\\"\\\"Create a simple JSON flow for testing.\\\"\\\"\\\"\\n        return {\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"id\\\": \\\"ChatInput-1\\\",\\n                        \\\"type\\\": \\\"ChatInput\\\",\\n                        \\\"position\\\": {\\\"x\\\": 100, \\\"y\\\": 100},\\n                        \\\"data\\\": {\\\"display_name\\\": \\\"Chat Input\\\"},\\n                    },\\n                    {\\n                        \\\"id\\\": \\\"ChatOutput-1\\\",\\n                        \\\"type\\\": \\\"ChatOutput\\\",\\n                        \\\"position\\\": {\\\"x\\\": 400, \\\"y\\\": 100},\\n                        \\\"data\\\": {\\\"display_name\\\": \\\"Chat Output\\\"},\\n                    },\\n                ],\\n                \\\"edges\\\": [\\n                    {\\n                        \\\"id\\\": \\\"edge-1\\\",\\n                        \\\"source\\\": \\\"ChatInput-1\\\",\\n                        \\\"target\\\": \\\"ChatOutput-1\\\",\\n                        \\\"sourceHandle\\\": \\\"message_response\\\",\\n                        \\\"targetHandle\\\": \\\"input_value\\\",\\n                    }\\n                ],\\n            }\\n        }\\n\\n    def test_execute_input_validation_no_sources(self):\\n        \\\"\\\"\\\"Test that execute raises exit code 1 when no input source is provided.\\\"\\\"\\\"\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=None,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_execute_input_validation_multiple_sources(self, simple_chat_script):\\n        \\\"\\\"\\\"Test that execute raises exit code 1 when multiple input sources are provided.\\\"\\\"\\\"\\n        # Test script_path + flow_json\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=simple_chat_script,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json='{\\\"data\\\": {\\\"nodes\\\": []}}',\\n                stdin=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n        # Test flow_json + stdin\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=None,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json='{\\\"data\\\": {\\\"nodes\\\": []}}',\\n                stdin=True,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_execute_python_script_success(self, simple_chat_script, capsys):\\n        \\\"\\\"\\\"Test executing a valid Python script.\\\"\\\"\\\"\\n        # Test that Python script execution either succeeds or fails gracefully\\n        # ``run`` is a typer command, so any parameter with a ``typer.Option(...)`` default\\n        # (e.g. session_id) needs to be passed explicitly when invoking outside typer's\\n        # parser \u2014 otherwise the default evaluates to a ``typer.models.OptionInfo``\\n        # sentinel and propagates downstream.\\n        with contextlib.suppress(typer.Exit):\\n            run(\\n                script_path=simple_chat_script,\\n                input_value=\\\"Hello, world!\\\",\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n                session_id=None,\\n            )\\n\\n        # Test passes as long as no unhandled exceptions occur\\n\\n        # Check that output was produced\\n        captured = capsys.readouterr()\\n        if captured.out:\\n            # Should be valid JSON when successful\\n            # Output should always be valid JSON when verbose=False\\n            output_data = json.loads(captured.out)\\n            assert isinstance(output_data, dict)\\n            # Either success with result or error with error field\\n            assert \\\"result\\\" in output_data or \\\"error\\\" in output_data\\n\\n    def test_execute_python_script_verbose(self, simple_chat_script, capsys):\\n        \\\"\\\"\\\"Test executing a Python script with verbose output.\\\"\\\"\\\"\\n        # Test that verbose mode execution either succeeds or fails gracefully\\n        # See note in ``test_execute_python_script_success`` re: session_id=None.\\n        with contextlib.suppress(typer.Exit):\\n            run(\\n                script_path=simple_chat_script,\\n                input_value=\\\"Hello, world!\\\",\\n                input_value_option=None,\\n                verbose=True,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n                session_id=None,\\n            )\\n\\n        # Test passes as long as no unhandled exceptions occur\\n\\n        # In verbose mode, there should be diagnostic output\\n        captured = capsys.readouterr()\\n        # Verbose mode should show diagnostic messages in stderr\\n        assert len(captured.out + captured.err) > 0\\n\\n    def test_execute_python_script_different_formats(self, simple_chat_script):\\n        \\\"\\\"\\\"Test executing a Python script with different output formats.\\\"\\\"\\\"\\n        formats = [\\\"json\\\", \\\"text\\\", \\\"message\\\", \\\"result\\\"]\\n\\n        for output_format in formats:\\n            # Test that each format either succeeds or fails gracefully\\n            with contextlib.suppress(typer.Exit):\\n                run(\\n                    script_path=simple_chat_script,\\n                    input_value=\\\"Test input\\\",\\n                    input_value_option=None,\\n                    verbose=False,\\n                    output_format=output_format,\\n                    flow_json=None,\\n                    stdin=False,\\n                )\\n\\n            # Test passes as long as no unhandled exceptions occur\\n\\n    def test_execute_file_not_exists(self, tmp_path):\\n        \\\"\\\"\\\"Test execute with non-existent file raises exit code 1.\\\"\\\"\\\"\\n        non_existent_file = tmp_path / \\\"does_not_exist.py\\\"\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=non_existent_file,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_execute_invalid_file_extension(self, tmp_path):\\n        \\\"\\\"\\\"Test execute with invalid file extension raises exit code 1.\\\"\\\"\\\"\\n        txt_file = tmp_path / \\\"test.txt\\\"\\n        txt_file.write_text(\\\"not a script\\\")\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=txt_file,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_execute_python_script_no_graph_variable(self, invalid_script):\\n        \\\"\\\"\\\"Test execute with Python script that has no graph variable.\\\"\\\"\\\"\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=invalid_script,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_execute_python_script_syntax_error(self, syntax_error_script):\\n        \\\"\\\"\\\"Test execute with Python script that has syntax errors.\\\"\\\"\\\"\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=syntax_error_script,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_execute_flow_json_valid(self, simple_json_flow):\\n        \\\"\\\"\\\"Test execute with valid flow_json.\\\"\\\"\\\"\\n        flow_json_str = json.dumps(simple_json_flow)\\n\\n        # Test that JSON flow execution either succeeds or fails gracefully\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=None,\\n                input_value=\\\"Hello JSON!\\\",\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=flow_json_str,\\n                stdin=False,\\n            )\\n\\n        # The function should exit cleanly (either success or expected failure)\\n        assert exc_info.value.exit_code in [0, 1]\\n\\n    def test_execute_flow_json_invalid(self):\\n        \\\"\\\"\\\"Test execute with invalid flow_json raises exit code 1.\\\"\\\"\\\"\\n        invalid_json = '{\\\"nodes\\\": [invalid json'\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=None,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=invalid_json,\\n                stdin=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    @patch(\\\"sys.stdin\\\")\\n    def test_execute_stdin_valid(self, mock_stdin, simple_json_flow):\\n        \\\"\\\"\\\"Test execute with valid stdin input.\\\"\\\"\\\"\\n        flow_json_str = json.dumps(simple_json_flow)\\n        mock_stdin.read.return_value = flow_json_str\\n\\n        # Test that stdin execution either succeeds or fails gracefully.\\n        # See note in ``test_execute_python_script_success`` re: session_id=None.\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=None,\\n                input_value=\\\"Hello stdin!\\\",\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=True,\\n                session_id=None,\\n            )\\n\\n        # Check that stdin was read and function exited cleanly\\n        mock_stdin.read.assert_called_once()\\n        assert exc_info.value.exit_code in [0, 1]\\n\\n    @patch(\\\"sys.stdin\\\")\\n    def test_execute_stdin_empty(self, mock_stdin):\\n        \\\"\\\"\\\"Test execute with empty stdin raises exit code 1.\\\"\\\"\\\"\\n        mock_stdin.read.return_value = \\\"\\\"\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=None,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=True,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    @patch(\\\"sys.stdin\\\")\\n    def test_execute_stdin_invalid(self, mock_stdin):\\n        \\\"\\\"\\\"Test execute with invalid stdin JSON raises exit code 1.\\\"\\\"\\\"\\n        mock_stdin.read.return_value = '{\\\"nodes\\\": [invalid json'\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=None,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=True,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_execute_input_value_precedence(self, simple_chat_script, capsys):\\n        \\\"\\\"\\\"Test that positional input_value takes precedence over --input-value option.\\\"\\\"\\\"\\n        # Test that input precedence works and execution either succeeds or fails gracefully\\n        with contextlib.suppress(typer.Exit):\\n            run(\\n                script_path=simple_chat_script,\\n                input_value=\\\"positional_value\\\",\\n                input_value_option=\\\"option_value\\\",\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n            )\\n\\n        # Test passes as long as no unhandled exceptions occur\\n\\n        # If successful, verify that positional value was used\\n        captured = capsys.readouterr()\\n        if captured.out and \\\"positional_value\\\" in captured.out:\\n            # Positional value was used correctly\\n            assert True\\n\\n    def test_execute_directory_instead_of_file(self, tmp_path):\\n        \\\"\\\"\\\"Test execute with directory instead of file raises exit code 1.\\\"\\\"\\\"\\n        directory = tmp_path / \\\"test_dir\\\"\\n        directory.mkdir()\\n\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=directory,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n            )\\n        assert exc_info.value.exit_code == 1\\n\\n    def test_execute_json_flow_with_temporary_file_cleanup(self, simple_json_flow):\\n        \\\"\\\"\\\"Test that temporary files are cleaned up when using flow_json.\\\"\\\"\\\"\\n        flow_json_str = json.dumps(simple_json_flow)\\n\\n        # Count temporary files before\\n        temp_dir = Path(tempfile.gettempdir())\\n        temp_files_before = list(temp_dir.glob(\\\"*.json\\\"))\\n\\n        with contextlib.suppress(typer.Exit):\\n            run(\\n                script_path=None,\\n                input_value=\\\"Test cleanup\\\",\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=flow_json_str,\\n                stdin=False,\\n            )\\n\\n        # Count temporary files after\\n        temp_files_after = list(temp_dir.glob(\\\"*.json\\\"))\\n\\n        # Should not have more temp files than before (cleanup working)\\n        assert len(temp_files_after) <= len(temp_files_before) + 1  # Allow for one potential leftover\\n\\n    def test_execute_verbose_error_output(self, invalid_script, capsys):\\n        \\\"\\\"\\\"Test that verbose mode shows error details.\\\"\\\"\\\"\\n        # See note in ``test_execute_python_script_success`` re: session_id=None.\\n        with pytest.raises(typer.Exit) as exc_info:\\n            run(\\n                script_path=invalid_script,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=True,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n                session_id=None,\\n            )\\n\\n        assert exc_info.value.exit_code == 1\\n        captured = capsys.readouterr()\\n        # Verbose mode should show error details\\n        error_output = captured.out + captured.err\\n        assert \\\"graph\\\" in error_output.lower() or \\\"variable\\\" in error_output.lower()\\n\\n    def test_session_id_cli_flag_plumbs_through_to_run_flow(self, simple_chat_script):\\n        \\\"\\\"\\\"--session-id is wired from typer through `run` into `run_flow(session_id=...)`.\\n\\n        Locks in the typer Option name so a rename or wiring typo at lfx.cli.run.run\\n        is caught here (the unit tests on run_flow itself only cover the function\\n        contract, not this CLI layer).\\n        \\\"\\\"\\\"\\n        captured = {}\\n\\n        async def fake_run_flow(**kwargs):\\n            captured.update(kwargs)\\n            return {\\\"success\\\": True, \\\"result\\\": \\\"ok\\\", \\\"logs\\\": \\\"\\\"}\\n\\n        with patch(\\\"lfx.cli.run.run_flow\\\", new=AsyncMock(side_effect=fake_run_flow)):\\n            run(\\n                script_path=simple_chat_script,\\n                input_value=\\\"hi\\\",\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n                session_id=\\\"my-fixed-session\\\",\\n            )\\n\\n        assert captured.get(\\\"session_id\\\") == \\\"my-fixed-session\\\"\\n\\n    def test_session_id_cli_flag_omitted_passes_none(self, simple_chat_script):\\n        \\\"\\\"\\\"No --session-id => `run_flow` receives session_id=None (auto-gen happens downstream).\\\"\\\"\\\"\\n        captured = {}\\n\\n        async def fake_run_flow(**kwargs):\\n            captured.update(kwargs)\\n            return {\\\"success\\\": True, \\\"result\\\": \\\"ok\\\", \\\"logs\\\": \\\"\\\"}\\n\\n        with patch(\\\"lfx.cli.run.run_flow\\\", new=AsyncMock(side_effect=fake_run_flow)):\\n            run(\\n                script_path=simple_chat_script,\\n                input_value=\\\"hi\\\",\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n                session_id=None,\\n            )\\n\\n        assert captured.get(\\\"session_id\\\") is None\\n\\n    def test_execute_without_input_value(self, simple_chat_script, capsys):\\n        \\\"\\\"\\\"Test executing without providing input value.\\\"\\\"\\\"\\n        # Test that execution without input either succeeds or fails gracefully\\n        with contextlib.suppress(typer.Exit):\\n            run(\\n                script_path=simple_chat_script,\\n                input_value=None,\\n                input_value_option=None,\\n                verbose=False,\\n                output_format=\\\"json\\\",\\n                flow_json=None,\\n                stdin=False,\\n            )\\n\\n        # Test passes as long as no unhandled exceptions occur\\n\\n        # Check that output was produced\\n        captured = capsys.readouterr()\\n        if captured.out:\\n            # Should be valid JSON when successful\\n            try:\\n                output_data = json.loads(captured.out)\\n                assert isinstance(output_data, dict)\\n            except json.JSONDecodeError:\\n                assert len(captured.out.strip()) >= 0\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_run_command_otlp_export.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"61f5f96ced5eb21ba263afa0f6d9bf4ecb661407421543d01921ca056dcc7d13\",\"content\":\"\\\"\\\"\\\"``lfx run`` must deliver its flow span over the production OTLP pipeline, not only label it.\\n\\nThe sibling ``test_run_command_flow_span.py`` installs an in-memory tracer provider before it\\ninvokes the command, which proves the ``protocol`` attribute is bound on the right span. It\\ncannot prove what an operator actually gets, which needs two things the command itself has to\\ndo: install the providers from ``OTEL_EXPORTER_OTLP_*`` and flush them before the one-shot\\nprocess exits. Neither happened: the command never called\\n:func:`lfx.observability.bootstrap_application_telemetry`, so the span landed on OpenTelemetry's\\nno-op proxy provider and every ``lfx run`` wired into an APM was a silently blind surface.\\n\\nThis drives the real console entry point in a subprocess, with the standard environment\\nvariables pointed at a loopback OTLP/HTTP collector, and reads the span off the protobuf that\\narrived. The batch processor's own export timer is pushed out to ten minutes, so the only thing\\nthat can deliver the span is the explicit flush on exit; a run that exported only because the\\ntimer happened to fire would not pass here.\\n\\\"\\\"\\\"\\n\\nimport gzip\\nimport http.server\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\nimport threading\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n# opentelemetry is an optional lfx extra (``lfx[otel]``); skip rather than error on an install\\n# that did not opt in, matching the sibling probes. Probed through the OTLP/HTTP trace exporter\\n# rather than the bare ``opentelemetry`` namespace, which opentelemetry-api alone satisfies: this\\n# file needs the exporter the command installs in the subprocess and the proto module the\\n# collector decodes with, and the exporter import brings both (plus the SDK) or fails.\\npytest.importorskip(\\\"opentelemetry.exporter.otlp.proto.http.trace_exporter\\\")\\nfrom lfx.observability import APPLICATION_TRACER_NAME\\nfrom opentelemetry.proto.collector.trace.v1.trace_service_pb2 import ExportTraceServiceRequest\\n\\nFLOW = Path(__file__).resolve().parents[2] / \\\"data\\\" / \\\"simple_chat_no_llm.json\\\"\\n\\n# A flow whose component raises, so the run ends with the error JSON and exit code 1. The span\\n# for that run is the one an operator most needs delivered: it is the only record that a cron\\n# job or CI step failed, and it must not be lost to a flush that only happens on success.\\nFAILING_FLOW_SCRIPT = \\\"\\\"\\\"\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.graph import Graph\\nfrom lfx.io import MessageInput, Output\\nfrom lfx.schema.message import Message\\n\\n\\nclass ExplodingComponent(Component):\\n    display_name = \\\"Exploding\\\"\\n    inputs = [MessageInput(name=\\\"input_value\\\", display_name=\\\"Input\\\")]\\n    outputs = [Output(name=\\\"message\\\", display_name=\\\"Message\\\", method=\\\"explode\\\")]\\n\\n    def explode(self) -> Message:\\n        msg = \\\"inventory service returned 503\\\"\\n        raise RuntimeError(msg)\\n\\n\\nchat_input = ChatInput()\\nexploding = ExplodingComponent().set(input_value=chat_input.message_response)\\nchat_output = ChatOutput().set(input_value=exploding.explode)\\ngraph = Graph(chat_input, chat_output)\\n\\\"\\\"\\\"\\n\\n\\nclass _Collector(http.server.BaseHTTPRequestHandler):\\n    def do_POST(self) -> None:\\n        body = self.rfile.read(int(self.headers.get(\\\"Content-Length\\\", 0)))\\n        if self.headers.get(\\\"Content-Encoding\\\") == \\\"gzip\\\":\\n            body = gzip.decompress(body)\\n        self.server.requests.append((self.path, body))\\n        self.send_response(200)\\n        self.send_header(\\\"Content-Length\\\", \\\"0\\\")\\n        self.end_headers()\\n\\n    def log_message(self, *args) -> None:\\n        pass\\n\\n\\n@pytest.fixture\\ndef collector():\\n    server = http.server.HTTPServer((\\\"127.0.0.1\\\", 0), _Collector)\\n    server.requests = []\\n    thread = threading.Thread(target=server.serve_forever, daemon=True)\\n    thread.start()\\n    yield server\\n    server.shutdown()\\n    server.server_close()\\n    thread.join(timeout=5)\\n\\n\\ndef _run_cli(collector, *args: str) -> subprocess.CompletedProcess:\\n    \\\"\\\"\\\"Run ``lfx run`` exactly as an operator would, exporting to the loopback collector.\\\"\\\"\\\"\\n    # Start from a clean slate so the developer's own OTEL_* vars cannot skew the result.\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env[\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\"] = f\\\"http://127.0.0.1:{collector.server_address[1]}\\\"\\n    # Ten minutes: the span must arrive because the command flushed on exit, not because the\\n    # batch processor's timer fired while the run was still going.\\n    env[\\\"OTEL_BSP_SCHEDULE_DELAY\\\"] = \\\"600000\\\"\\n    return subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-m\\\", \\\"lfx\\\", \\\"run\\\", *args],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=300,\\n        check=False,\\n    )\\n\\n\\ndef _flow_spans(requests) -> list[dict]:\\n    spans = []\\n    for path, body in requests:\\n        if path != \\\"/v1/traces\\\":\\n            continue\\n        request = ExportTraceServiceRequest()\\n        request.ParseFromString(body)\\n        for resource_spans in request.resource_spans:\\n            for scope_spans in resource_spans.scope_spans:\\n                for span in scope_spans.spans:\\n                    if span.name != \\\"flow.execute\\\":\\n                        continue\\n                    spans.append(\\n                        {\\n                            \\\"scope\\\": scope_spans.scope.name,\\n                            \\\"attrs\\\": {a.key: a.value.string_value for a in span.attributes},\\n                        }\\n                    )\\n    return spans\\n\\n\\ndef _the_one_json_line(stdout: str) -> dict:\\n    \\\"\\\"\\\"The CLI's stdout contract: one JSON document, nothing else. Telemetry must not break it.\\\"\\\"\\\"\\n    lines = [line for line in stdout.splitlines() if line.strip()]\\n    assert len(lines) == 1, stdout\\n    return json.loads(lines[0])\\n\\n\\ndef test_a_run_exports_its_flow_span_over_otlp(collector):\\n    completed = _run_cli(collector, str(FLOW), \\\"--input-value\\\", \\\"hello operator\\\")\\n\\n    assert completed.returncode == 0, completed.stderr\\n    assert _the_one_json_line(completed.stdout)[\\\"success\\\"] is True\\n\\n    spans = _flow_spans(collector.requests)\\n    assert len(spans) == 1, f\\\"expected exactly one flow span at the collector, got {spans}\\\"\\n    assert spans[0][\\\"scope\\\"] == APPLICATION_TRACER_NAME\\n    assert spans[0][\\\"attrs\\\"][\\\"protocol\\\"] == \\\"lfx.run\\\"\\n    assert spans[0][\\\"attrs\\\"][\\\"status\\\"] == \\\"ok\\\"\\n\\n\\ndef test_a_failed_run_still_exports_its_flow_span(collector, tmp_path):\\n    # A file rather than inline JSON: Component.__init__ reads its own class source with\\n    # inspect.getsource, which has nothing to read for a class defined in a ``-c`` string.\\n    script = tmp_path / \\\"failing_flow.py\\\"\\n    script.write_text(FAILING_FLOW_SCRIPT, encoding=\\\"utf-8\\\")\\n\\n    completed = _run_cli(collector, str(script), \\\"--input-value\\\", \\\"hello operator\\\")\\n\\n    assert completed.returncode == 1, completed.stdout + completed.stderr\\n    assert _the_one_json_line(completed.stdout)[\\\"success\\\"] is False\\n\\n    spans = _flow_spans(collector.requests)\\n    assert len(spans) == 1, f\\\"expected exactly one flow span at the collector, got {spans}\\\"\\n    assert spans[0][\\\"attrs\\\"][\\\"protocol\\\"] == \\\"lfx.run\\\"\\n    assert spans[0][\\\"attrs\\\"][\\\"status\\\"] == \\\"error\\\"\\n    assert spans[0][\\\"attrs\\\"].get(\\\"error.type\\\"), spans[0][\\\"attrs\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_run_command_telemetry_lifecycle.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3328f2666b3da2fb26173737e1c0ef1c4fb6f52e96245b75e98fa5eb395bfb4e\",\"content\":\"\\\"\\\"\\\"``lfx run`` owns the telemetry lifetime of its one-shot process, and the order is the point.\\n\\nThe wire test next door (``test_run_command_otlp_export.py``) proves delivery end to end. This\\none pins the ordering cheaply, in-process and without OpenTelemetry installed: the providers\\nmust be bootstrapped before the run (a span created earlier lands on the no-op proxy provider\\nand is gone), the protocol must be bound while the run executes, and the flush must happen\\nafter the run ends, on every exit path. A flush that only ran on success would lose exactly the\\nspan an operator most needs, the ``status=error`` one from the cron job that broke. The result is\\nechoed before the flush, so a consumer reading stdout is never held behind the export; that is\\nasserted as an ordering too, since a stdout check after the fact cannot tell the two apart.\\n\\\"\\\"\\\"\\n\\nfrom pathlib import Path\\n\\nimport pytest\\nimport typer\\nfrom lfx.cli.run import run\\nfrom lfx.observability import get_execution_protocol\\nfrom lfx.run.base import RunError\\n\\n\\nclass _RecordingTelemetry:\\n    def __init__(self, events: list[str]) -> None:\\n        self._events = events\\n\\n    def shutdown(self) -> None:\\n        self._events.append(\\\"shutdown\\\")\\n\\n\\n@pytest.fixture\\ndef events(monkeypatch):\\n    \\\"\\\"\\\"Record the order of bootstrap, run, echo, and shutdown; ``run_flow`` itself is stubbed.\\\"\\\"\\\"\\n    recorded: list[str] = []\\n\\n    def fake_bootstrap(**_kwargs):\\n        recorded.append(\\\"bootstrap\\\")\\n        return _RecordingTelemetry(recorded)\\n\\n    original_echo = typer.echo\\n\\n    def recording_echo(*args, **kwargs):\\n        recorded.append(\\\"echo\\\")\\n        return original_echo(*args, **kwargs)\\n\\n    monkeypatch.setattr(\\\"lfx.cli.run.bootstrap_application_telemetry\\\", fake_bootstrap)\\n    monkeypatch.setattr(\\\"lfx.cli.run.typer.echo\\\", recording_echo)\\n    return recorded\\n\\n\\ndef _invoke() -> None:\\n    run(\\n        script_path=Path(\\\"unused.json\\\"),\\n        input_value=None,\\n        input_value_option=\\\"hello operator\\\",\\n        output_format=\\\"json\\\",\\n        flow_json=None,\\n        stdin=False,\\n    )\\n\\n\\ndef test_bootstrap_precedes_the_run_and_shutdown_follows_it(events, monkeypatch, capsys):\\n    async def fake_run_flow(**_kwargs):\\n        events.append(f\\\"run_flow protocol={get_execution_protocol()}\\\")\\n        return {\\\"result\\\": \\\"hello operator\\\", \\\"success\\\": True}\\n\\n    monkeypatch.setattr(\\\"lfx.cli.run.run_flow\\\", fake_run_flow)\\n\\n    _invoke()\\n\\n    # The result is echoed before the flush, so a consumer reading stdout is never held behind\\n    # the export.\\n    assert events == [\\\"bootstrap\\\", \\\"run_flow protocol=lfx.run\\\", \\\"echo\\\", \\\"shutdown\\\"]\\n    assert '\\\"success\\\": true' in capsys.readouterr().out\\n\\n\\ndef test_a_failed_run_still_flushes(events, monkeypatch):\\n    async def fake_run_flow(**_kwargs):\\n        events.append(\\\"run_flow\\\")\\n        msg = \\\"component exploded\\\"\\n        raise RunError(msg)\\n\\n    monkeypatch.setattr(\\\"lfx.cli.run.run_flow\\\", fake_run_flow)\\n\\n    with pytest.raises(typer.Exit) as exc_info:\\n        _invoke()\\n\\n    assert exc_info.value.exit_code == 1\\n    # The error JSON, too, is out before the flush.\\n    assert events == [\\\"bootstrap\\\", \\\"run_flow\\\", \\\"echo\\\", \\\"shutdown\\\"]\\n\\n\\ndef test_an_unexpected_exception_still_flushes(events, monkeypatch):\\n    \\\"\\\"\\\"Not only the error the command knows how to report: anything that escapes the run.\\\"\\\"\\\"\\n\\n    async def fake_run_flow(**_kwargs):\\n        events.append(\\\"run_flow\\\")\\n        msg = \\\"something the command did not anticipate\\\"\\n        raise RuntimeError(msg)\\n\\n    monkeypatch.setattr(\\\"lfx.cli.run.run_flow\\\", fake_run_flow)\\n\\n    with pytest.raises(RuntimeError):\\n        _invoke()\\n\\n    # Nothing is echoed for an exception the command does not know how to report; the flush\\n    # still runs.\\n    assert events == [\\\"bootstrap\\\", \\\"run_flow\\\", \\\"shutdown\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_run_starter_projects.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"14c1d499fe4f4befe2589d44479a715b37fe2975dcd32ca0d9e33b5d02f3c320\",\"content\":\"\\\"\\\"\\\"Test run command with all starter project templates.\\n\\nTests that all starter project JSON files can be loaded by lfx run command\\nwithout import errors for langflow modules. We expect execution errors\\n(missing API keys, etc.) but no import/module errors.\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.__main__ import app\\nfrom typer.testing import CliRunner\\n\\nrunner = CliRunner()\\n\\n\\ndef get_starter_projects_path() -> Path:\\n    \\\"\\\"\\\"Get path to starter projects directory.\\\"\\\"\\\"\\n    # Use absolute path to find the starter projects\\n    test_file_path = Path(__file__).resolve()\\n\\n    # Navigate up to find the langflow project root\\n    current = test_file_path.parent\\n    while current != current.parent:\\n        if (current / \\\"src\\\" / \\\"backend\\\" / \\\"base\\\" / \\\"langflow\\\" / \\\"initial_setup\\\" / \\\"starter_projects\\\").exists():\\n            return current / \\\"src\\\" / \\\"backend\\\" / \\\"base\\\" / \\\"langflow\\\" / \\\"initial_setup\\\" / \\\"starter_projects\\\"\\n        current = current.parent\\n\\n    # Fallback to a relative path from the test file\\n    # test_file is in: src/lfx/tests/unit/cli\\n    # starter projects are in: src/backend/base/langflow/initial_setup/starter_projects\\n    project_root = test_file_path.parent.parent.parent.parent.parent\\n    return project_root / \\\"backend\\\" / \\\"base\\\" / \\\"langflow\\\" / \\\"initial_setup\\\" / \\\"starter_projects\\\"\\n\\n\\ndef get_starter_project_files():\\n    \\\"\\\"\\\"Get all starter project JSON files for parameterization.\\\"\\\"\\\"\\n    starter_path = get_starter_projects_path()\\n    if not starter_path.exists():\\n        return []\\n    return sorted(starter_path.glob(\\\"*.json\\\"))\\n\\n\\nclass TestRunStarterProjects:\\n    \\\"\\\"\\\"Test run command with all starter project templates.\\\"\\\"\\\"\\n\\n    def test_starter_projects_exist(self):\\n        \\\"\\\"\\\"Test that starter projects directory exists and has templates.\\\"\\\"\\\"\\n        path = get_starter_projects_path()\\n        assert path.exists(), f\\\"Starter projects directory not found: {path}\\\"\\n\\n        templates = get_starter_project_files()\\n        assert len(templates) > 0, \\\"No starter project files found\\\"\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files(), ids=lambda x: x.name)\\n    def test_run_starter_project_no_import_errors(self, template_file):\\n        \\\"\\\"\\\"Test that starter project can be loaded without langflow or lfx import errors.\\n\\n        We expect execution errors (missing API keys, missing inputs, etc.)\\n        but there should be NO errors about importing langflow or lfx modules.\\n        \\\"\\\"\\\"\\n        # Run the command with --no-check-variables to skip variable validation\\n        # Use verbose mode to get detailed error messages in stderr\\n        result = runner.invoke(\\n            app,\\n            [\\\"run\\\", \\\"--verbose\\\", \\\"--no-check-variables\\\", str(template_file), \\\"test input\\\"],\\n        )\\n\\n        # The command will likely fail due to missing API keys, etc.\\n        # But we're checking that there are no import errors\\n\\n        # Use the combined output provided by Click/Typer\\n        all_output = result.output\\n\\n        # Check for import errors related to langflow or lfx\\n        if \\\"ModuleNotFoundError\\\" in all_output or \\\"ImportError\\\" in all_output or \\\"Module\\\" in all_output:\\n            # Check for langflow import errors\\n            if \\\"No module named 'langflow'\\\" in all_output or \\\"Module langflow\\\" in all_output:\\n                # Extract the specific error for better debugging\\n                error_line = \\\"\\\"\\n                for line in all_output.split(\\\"\\\\n\\\"):\\n                    if \\\"langflow\\\" in line and (\\\"No module named\\\" in line or \\\"Module\\\" in line):\\n                        error_line = line.strip()\\n                        break\\n                pytest.fail(f\\\"Langflow import error found in {template_file.name}.\\\\nError: {error_line}\\\")\\n\\n            # Check for lfx import errors (these indicate structural issues)\\n            if \\\"No module named 'lfx.\\\" in all_output or \\\"Module lfx.\\\" in all_output:\\n                # Extract the specific error for better debugging\\n                import re\\n\\n                # Remove ANSI color codes for cleaner output\\n                clean_output = re.sub(r\\\"\\\\x1b\\\\[[0-9;]*m\\\", \\\"\\\", all_output)\\n\\n                error_lines = []\\n                for line in clean_output.split(\\\"\\\\n\\\"):\\n                    if \\\"lfx\\\" in line and (\\\"No module named\\\" in line or \\\"Module lfx.\\\" in line):\\n                        # Extract just the module name from various error formats\\n                        if \\\"No module named\\\" in line:\\n                            match = re.search(r\\\"No module named ['\\\\\\\"]([^'\\\\\\\"]+)['\\\\\\\"]\\\", line)\\n                            if match:\\n                                error_lines.append(f\\\"  - Missing module: {match.group(1)}\\\")\\n                        elif \\\"Module lfx.\\\" in line and \\\"not found\\\" in line:\\n                            match = re.search(r\\\"Module (lfx\\\\.[^\\\\s]+)\\\", line)\\n                            if match:\\n                                error_lines.append(f\\\"  - Missing module: {match.group(1)}\\\")\\n\\n                # Deduplicate while preserving order\\n                seen = set()\\n                unique_errors = []\\n                for error in error_lines:\\n                    if error not in seen:\\n                        seen.add(error)\\n                        unique_errors.append(error)\\n\\n                error_detail = \\\"\\\\n\\\".join(unique_errors[:5])  # Show first 5 unique lfx errors\\n                pytest.fail(\\n                    f\\\"LFX import error found in {template_file.name}.\\\\n\\\"\\n                    f\\\"This indicates lfx internal structure issues.\\\\n\\\"\\n                    f\\\"Missing modules:\\\\n{error_detail}\\\"\\n                )\\n\\n            # Check for other critical import errors\\n            if \\\"cannot import name\\\" in all_output and (\\\"langflow\\\" in all_output or \\\"lfx\\\" in all_output):\\n                # Extract the specific import error\\n                error_line = \\\"\\\"\\n                for line in all_output.split(\\\"\\\\n\\\"):\\n                    if \\\"cannot import name\\\" in line:\\n                        error_line = line.strip()\\n                        break\\n                pytest.fail(f\\\"Import error found in {template_file.name}.\\\\nError: {error_line}\\\")\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files(), ids=lambda x: x.name)\\n    def test_run_starter_project_valid_json(self, template_file):\\n        \\\"\\\"\\\"Test that starter project file is valid JSON.\\\"\\\"\\\"\\n        with template_file.open(encoding=\\\"utf-8\\\") as f:\\n            try:\\n                data = json.load(f)\\n                # Basic structure validation\\n                assert \\\"data\\\" in data or \\\"nodes\\\" in data, f\\\"Missing 'data' or 'nodes' in {template_file.name}\\\"\\n            except json.JSONDecodeError as e:\\n                pytest.fail(f\\\"Invalid JSON in {template_file.name}: {e}\\\")\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files(), ids=lambda x: x.name)\\n    def test_run_starter_project_format_options(self, template_file):\\n        \\\"\\\"\\\"Test that starter projects can be run with different output formats.\\n\\n        This tests that the basic command parsing works, even if execution fails.\\n        \\\"\\\"\\\"\\n        formats = [\\\"json\\\", \\\"text\\\", \\\"message\\\", \\\"result\\\"]\\n\\n        for fmt in formats:\\n            result = runner.invoke(\\n                app,\\n                [\\\"run\\\", \\\"--format\\\", fmt, \\\"--no-check-variables\\\", str(template_file), \\\"test\\\"],\\n            )\\n\\n            # We don't check exit code as it may fail due to missing dependencies\\n            # We just want to ensure the command is parsed and attempted\\n\\n            # Check that we got some output (even if it's an error)\\n            assert len(result.output) > 0, f\\\"No output for {template_file.name} with format {fmt}\\\"\\n\\n    def test_run_basic_starter_projects_detailed(self):\\n        \\\"\\\"\\\"Test basic starter projects that should have minimal dependencies.\\\"\\\"\\\"\\n        basic_templates = [\\n            \\\"Basic Prompting.json\\\",\\n            \\\"Basic Prompt Chaining.json\\\",\\n        ]\\n\\n        starter_path = get_starter_projects_path()\\n\\n        for template_name in basic_templates:\\n            template_file = starter_path / template_name\\n            if not template_file.exists():\\n                continue\\n\\n            result = runner.invoke(\\n                app,\\n                [\\\"run\\\", \\\"--verbose\\\", \\\"--no-check-variables\\\", str(template_file), \\\"Hello test\\\"],\\n            )\\n\\n            # These basic templates might still fail due to missing LLM API keys\\n            # but should not have import errors\\n            all_output = result.output\\n\\n            # More specific checks for these basic templates\\n            assert \\\"No module named 'langflow'\\\" not in all_output, f\\\"Langflow import error in {template_name}\\\"\\n\\n            # Check for module not found errors specifically related to langflow\\n            # (Settings service errors are runtime errors, not import errors)\\n            if \\\"ModuleNotFoundError\\\" in all_output and \\\"langflow\\\" in all_output and \\\"lfx.services\\\" not in all_output:\\n                # This is an actual langflow import error, not an internal lfx error\\n                pytest.fail(f\\\"Module not found error for langflow in {template_name}\\\")\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files()[:5], ids=lambda x: x.name)\\n    def test_run_starter_project_with_stdin(self, template_file):\\n        \\\"\\\"\\\"Test loading starter projects via stdin (testing first 5 for speed).\\\"\\\"\\\"\\n        with template_file.open(encoding=\\\"utf-8\\\") as f:\\n            json_content = f.read()\\n\\n        result = runner.invoke(\\n            app,\\n            [\\\"run\\\", \\\"--stdin\\\", \\\"--no-check-variables\\\", \\\"--input-value\\\", \\\"test\\\"],\\n            input=json_content,\\n        )\\n\\n        # Check that the command attempted to process the input\\n        assert len(result.output) > 0\\n\\n        # Verify no import errors\\n        all_output = result.output\\n        assert \\\"No module named 'langflow'\\\" not in all_output\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files()[:5], ids=lambda x: x.name)\\n    def test_run_starter_project_inline_json(self, template_file):\\n        \\\"\\\"\\\"Test loading starter projects via --flow-json option (testing first 5 for speed).\\\"\\\"\\\"\\n        with template_file.open(encoding=\\\"utf-8\\\") as f:\\n            json_content = f.read()\\n\\n        result = runner.invoke(\\n            app,\\n            [\\\"run\\\", \\\"--flow-json\\\", json_content, \\\"--no-check-variables\\\", \\\"--input-value\\\", \\\"test\\\"],\\n        )\\n\\n        # Check that the command attempted to process the input\\n        assert len(result.output) > 0\\n\\n        # Verify no import errors\\n        all_output = result.output\\n        assert \\\"No module named 'langflow'\\\" not in all_output\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_run_starter_projects_backward_compatibility.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"18d79d9b18afb2cd91a3910ec1e7b389c435146c4730e376e44efc7eb21a66d8\",\"content\":\"\\\"\\\"\\\"Test run command with starter project templates from 1.6.0 for backwards compatibility.\\n\\nTests that all starter project JSON files from tag 1.6.0 can be loaded by lfx run command\\nwithout import errors for langflow modules. We expect execution errors\\n(missing API keys, etc.) but no import/module errors.\\n\\nThis ensures backwards compatibility with existing starter projects.\\n\\\"\\\"\\\"\\n\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.__main__ import app\\nfrom typer.testing import CliRunner\\n\\nrunner = CliRunner()\\n\\n\\ndef get_starter_projects_path() -> Path:\\n    \\\"\\\"\\\"Get path to starter projects directory.\\n\\n    Returns:\\n        Path to the 1.6.0 starter projects directory in tests/data.\\n    \\\"\\\"\\\"\\n    test_file_path = Path(__file__).resolve()\\n    return test_file_path.parent.parent.parent / \\\"data\\\" / \\\"starter_projects_1_6_0\\\"\\n\\n\\ndef get_starter_project_files():\\n    \\\"\\\"\\\"Get all starter project JSON files for parameterization.\\n\\n    Returns files in sorted order for deterministic test execution.\\n    \\\"\\\"\\\"\\n    starter_path = get_starter_projects_path()\\n    if not starter_path.exists():\\n        return []\\n    return sorted(starter_path.glob(\\\"*.json\\\"))\\n\\n\\nclass TestRunStarterProjectsBackwardCompatibility:\\n    \\\"\\\"\\\"Test run command with starter project templates from 1.6.0 for backwards compatibility.\\\"\\\"\\\"\\n\\n    def test_starter_projects_1_6_0_exist(self):\\n        \\\"\\\"\\\"Test that 1.6.0 starter projects directory exists and has templates.\\\"\\\"\\\"\\n        path = get_starter_projects_path()\\n        if not path.exists():\\n            pytest.fail(f\\\"1.6.0 starter projects cache directory not found: {path}\\\")\\n\\n        templates = get_starter_project_files()\\n        if len(templates) == 0:\\n            pytest.fail(f\\\"No 1.6.0 starter project files found in cache: {path}\\\")\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files(), ids=lambda x: x.name)\\n    def test_run_1_6_0_starter_project_no_import_errors(self, template_file):\\n        \\\"\\\"\\\"Test that 1.6.0 starter project can be loaded without langflow or lfx import errors.\\n\\n        We expect execution errors (missing API keys, missing inputs, etc.)\\n        but there should be NO errors about importing langflow or lfx modules.\\n\\n        Note: Some 1.6.0 starter projects contain components with import bugs that were\\n        fixed in later versions. These are marked as expected failures.\\n        \\\"\\\"\\\"\\n        # Known failing starter projects due to component-level import bugs in 1.6.0\\n        known_failing_projects = {\\n            \\\"News Aggregator.json\\\": \\\"Contains SaveToFile component with langflow.api import bug \\\"\\n            \\\"(fixed in later versions)\\\"\\n        }\\n\\n        if template_file.name in known_failing_projects:\\n            pytest.xfail(f\\\"Known 1.6.0 component bug: {known_failing_projects[template_file.name]}\\\")\\n        # Run the command with --no-check-variables to skip variable validation\\n        # Use verbose mode to get detailed error messages in stderr\\n        result = runner.invoke(\\n            app,\\n            [\\\"run\\\", \\\"--verbose\\\", \\\"--no-check-variables\\\", str(template_file), \\\"test input\\\"],\\n        )\\n\\n        # The command will likely fail due to missing API keys, etc.\\n        # But we're checking that there are no import errors\\n\\n        # Use the combined output provided by Click/Typer\\n        all_output = result.output\\n\\n        # Check for import errors related to langflow or lfx\\n        if \\\"ModuleNotFoundError\\\" in all_output or \\\"ImportError\\\" in all_output or \\\"Module\\\" in all_output:\\n            # Check for langflow import errors\\n            if \\\"No module named 'langflow'\\\" in all_output or \\\"Module langflow\\\" in all_output:\\n                # Extract the specific error for better debugging\\n                error_line = \\\"\\\"\\n                for line in all_output.split(\\\"\\\\n\\\"):\\n                    if \\\"langflow\\\" in line and (\\\"No module named\\\" in line or \\\"Module\\\" in line):\\n                        error_line = line.strip()\\n                        break\\n                pytest.fail(f\\\"Langflow import error found in 1.6.0 template {template_file.name}.\\\\nError: {error_line}\\\")\\n\\n            # Check for lfx import errors (these indicate structural issues)\\n            if \\\"No module named 'lfx.\\\" in all_output or \\\"Module lfx.\\\" in all_output:\\n                # Extract the specific error for better debugging\\n                import re\\n\\n                # Remove ANSI color codes for cleaner output\\n                clean_output = re.sub(r\\\"\\\\x1b\\\\[[0-9;]*m\\\", \\\"\\\", all_output)\\n\\n                error_lines = []\\n                for line in clean_output.split(\\\"\\\\n\\\"):\\n                    if \\\"lfx\\\" in line and (\\\"No module named\\\" in line or \\\"Module lfx.\\\" in line):\\n                        # Extract just the module name from various error formats\\n                        if \\\"No module named\\\" in line:\\n                            match = re.search(r\\\"No module named ['\\\\\\\"]([^'\\\\\\\"]+)['\\\\\\\"]\\\", line)\\n                            if match:\\n                                error_lines.append(f\\\"  - Missing module: {match.group(1)}\\\")\\n                        elif \\\"Module lfx.\\\" in line and \\\"not found\\\" in line:\\n                            match = re.search(r\\\"Module (lfx\\\\.[^\\\\s]+)\\\", line)\\n                            if match:\\n                                error_lines.append(f\\\"  - Missing module: {match.group(1)}\\\")\\n\\n                # Deduplicate while preserving order\\n                seen = set()\\n                unique_errors = []\\n                for error in error_lines:\\n                    if error not in seen:\\n                        seen.add(error)\\n                        unique_errors.append(error)\\n\\n                error_detail = \\\"\\\\n\\\".join(unique_errors[:5])  # Show first 5 unique lfx errors\\n                pytest.fail(\\n                    f\\\"LFX import error found in 1.6.0 template {template_file.name}.\\\\n\\\"\\n                    f\\\"This indicates lfx internal structure issues.\\\\n\\\"\\n                    f\\\"Missing modules:\\\\n{error_detail}\\\"\\n                )\\n\\n            # Check for other critical import errors\\n            if \\\"cannot import name\\\" in all_output and (\\\"langflow\\\" in all_output or \\\"lfx\\\" in all_output):\\n                # Extract the specific import error\\n                error_line = \\\"\\\"\\n                for line in all_output.split(\\\"\\\\n\\\"):\\n                    if \\\"cannot import name\\\" in line:\\n                        error_line = line.strip()\\n                        break\\n                pytest.fail(f\\\"Import error found in 1.6.0 template {template_file.name}.\\\\nError: {error_line}\\\")\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files(), ids=lambda x: x.name)\\n    def test_run_1_6_0_starter_project_format_options(self, template_file):\\n        \\\"\\\"\\\"Test that 1.6.0 starter projects can be run with different output formats.\\n\\n        This tests that the basic command parsing works, even if execution fails.\\n        \\\"\\\"\\\"\\n        formats = [\\\"json\\\", \\\"text\\\", \\\"message\\\", \\\"result\\\"]\\n\\n        for fmt in formats:\\n            result = runner.invoke(\\n                app,\\n                [\\\"run\\\", \\\"--format\\\", fmt, \\\"--no-check-variables\\\", str(template_file), \\\"test\\\"],\\n            )\\n\\n            # We don't check exit code as it may fail due to missing dependencies\\n            # We just want to ensure the command is parsed and attempted\\n\\n            # Check that we got some output (even if it's an error)\\n            if len(result.output) == 0:\\n                pytest.fail(f\\\"No output for 1.6.0 template {template_file.name} with format {fmt}\\\")\\n\\n    @pytest.mark.xfail(reason=\\\"CLI --format option doesn't apply to error messages\\\")\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files()[:1], ids=lambda x: x.name)\\n    def test_run_1_6_0_format_option_applies_to_errors(self, template_file):\\n        \\\"\\\"\\\"Test that --format option applies to error messages.\\n\\n        Currently fails: Error messages are always returned as JSON regardless of --format.\\n        This test documents the expected behavior for future CLI fixes.\\n        \\\"\\\"\\\"\\n        import json as json_module\\n\\n        # Test with text format - errors should be plain text, not JSON\\n        result = runner.invoke(\\n            app,\\n            [\\\"run\\\", \\\"--format\\\", \\\"text\\\", \\\"--no-check-variables\\\", str(template_file), \\\"test\\\"],\\n        )\\n\\n        # If we get an error (which we expect due to missing API keys), it should be plain text\\n        if result.exit_code != 0:\\n            # Should NOT be valid JSON when format is \\\"text\\\"\\n            try:\\n                json_module.loads(result.output)\\n                pytest.fail(\\n                    \\\"Error output is JSON format when --format text was specified. \\\"\\n                    \\\"Error messages should respect the --format option.\\\"\\n                )\\n            except json_module.JSONDecodeError:\\n                # This is the expected behavior - plain text error\\n                pass\\n\\n    @pytest.mark.xfail(reason=\\\"CLI --format option doesn't apply when --verbose is used\\\")\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files()[:1], ids=lambda x: x.name)\\n    def test_run_1_6_0_format_option_applies_with_verbose(self, template_file):\\n        \\\"\\\"\\\"Test that --format option applies even when --verbose is used.\\n\\n        Currently fails: --verbose output doesn't conform to --format specification.\\n        This test documents the expected behavior for future CLI fixes.\\n        \\\"\\\"\\\"\\n        import json as json_module\\n\\n        # Test with JSON format + verbose - all output should be valid JSON\\n        result = runner.invoke(\\n            app,\\n            [\\\"run\\\", \\\"--format\\\", \\\"json\\\", \\\"--verbose\\\", \\\"--no-check-variables\\\", str(template_file), \\\"test\\\"],\\n        )\\n\\n        # With --format json, even verbose output should be parseable as JSON\\n        # (or at least the final output should be JSON without mixed text logs)\\n        lines = result.output.strip().split(\\\"\\\\n\\\")\\n        last_line = lines[-1] if lines else \\\"\\\"\\n\\n        try:\\n            json_module.loads(last_line)\\n        except json_module.JSONDecodeError:\\n            pytest.fail(\\n                \\\"With --format json and --verbose, expected final output to be valid JSON. \\\"\\n                \\\"Verbose logs should not interfere with JSON output format.\\\"\\n            )\\n\\n    @pytest.mark.xfail(\\n        reason=\\\"1.6.0 basic templates have langflow import issues - components expect langflow package to be available\\\"\\n    )\\n    def test_run_basic_1_6_0_starter_projects_detailed(self):\\n        \\\"\\\"\\\"Test basic 1.6.0 starter projects that should have minimal dependencies.\\\"\\\"\\\"\\n        basic_templates = [\\n            \\\"Basic Prompting.json\\\",\\n            \\\"Basic Prompt Chaining.json\\\",\\n        ]\\n\\n        starter_path = get_starter_projects_path()\\n\\n        for template_name in basic_templates:\\n            template_file = starter_path / template_name\\n            if not template_file.exists():\\n                continue\\n\\n            result = runner.invoke(\\n                app,\\n                [\\\"run\\\", \\\"--verbose\\\", \\\"--no-check-variables\\\", str(template_file), \\\"Hello test\\\"],\\n            )\\n\\n            # These basic templates might still fail due to missing LLM API keys\\n            # but should not have import errors\\n            all_output = result.output\\n\\n            # More specific checks for these basic templates\\n            if \\\"No module named 'langflow'\\\" in all_output:\\n                pytest.fail(f\\\"Langflow import error in 1.6.0 template {template_name}\\\")\\n\\n            # Check for module not found errors specifically related to langflow\\n            # (Settings service errors are runtime errors, not import errors)\\n            if \\\"ModuleNotFoundError\\\" in all_output and \\\"langflow\\\" in all_output and \\\"lfx.services\\\" not in all_output:\\n                # This is an actual langflow import error, not an internal lfx error\\n                pytest.fail(f\\\"Module not found error for langflow in 1.6.0 template {template_name}\\\")\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files(), ids=lambda x: x.name)\\n    def test_run_1_6_0_starter_project_with_stdin(self, template_file):\\n        \\\"\\\"\\\"Test loading 1.6.0 starter projects via stdin.\\\"\\\"\\\"\\n        with template_file.open(encoding=\\\"utf-8\\\") as f:\\n            json_content = f.read()\\n\\n        result = runner.invoke(\\n            app,\\n            [\\\"run\\\", \\\"--stdin\\\", \\\"--no-check-variables\\\", \\\"--input-value\\\", \\\"test\\\"],\\n            input=json_content,\\n        )\\n\\n        # Check that the command attempted to process the input\\n        if len(result.output) == 0:\\n            pytest.fail(\\\"No output from 1.6.0 stdin test\\\")\\n\\n        # Verify no import errors\\n        all_output = result.output\\n        if \\\"No module named 'langflow'\\\" in all_output:\\n            pytest.fail(\\\"Langflow import error in 1.6.0 stdin test\\\")\\n\\n    @pytest.mark.parametrize(\\\"template_file\\\", get_starter_project_files(), ids=lambda x: x.name)\\n    def test_run_1_6_0_starter_project_inline_json(self, template_file):\\n        \\\"\\\"\\\"Test loading 1.6.0 starter projects via --flow-json option.\\\"\\\"\\\"\\n        with template_file.open(encoding=\\\"utf-8\\\") as f:\\n            json_content = f.read()\\n\\n        result = runner.invoke(\\n            app,\\n            [\\\"run\\\", \\\"--flow-json\\\", json_content, \\\"--no-check-variables\\\", \\\"--input-value\\\", \\\"test\\\"],\\n        )\\n\\n        # Check that the command attempted to process the input\\n        if len(result.output) == 0:\\n            pytest.fail(\\\"No output from 1.6.0 inline JSON test\\\")\\n\\n        # Verify no import errors\\n        all_output = result.output\\n        if \\\"No module named 'langflow'\\\" in all_output:\\n            pytest.fail(\\\"Langflow import error in 1.6.0 inline JSON test\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_runtime_variables.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2dac986b9544619275813389d123fd72785a5b3035f6327cc467e5203884f8a9\",\"content\":\"import json\\n\\nfrom lfx.cli.runtime_variables import build_request_variables_from_global_vars\\nfrom lfx.services.variable.service import VariableService\\n\\n\\ndef test_build_request_variables_parses_langflow_request_variables():\\n    merged = {\\\"access_token\\\": \\\"from-json\\\", \\\"USER_ID\\\": \\\"u1\\\"}\\n    global_vars = {\\n        \\\"LANGFLOW_REQUEST_VARIABLES\\\": json.dumps(merged),\\n        \\\"access_token\\\": \\\"from-raw-override\\\",\\n        \\\"x-langflow-global-var-access-token\\\": \\\"alias-value\\\",\\n    }\\n    flat = build_request_variables_from_global_vars(global_vars)\\n    assert flat[\\\"access_token\\\"] == \\\"from-raw-override\\\"  # noqa: S105  # test value, not a credential\\n    assert flat[\\\"USER_ID\\\"] == \\\"u1\\\"\\n    assert flat[\\\"x-langflow-global-var-access-token\\\"] == \\\"alias-value\\\"\\n\\n\\ndef test_build_request_variables_keeps_raw_keys_when_blob_is_malformed():\\n    \\\"\\\"\\\"A malformed LANGFLOW_REQUEST_VARIABLES blob is skipped; raw keys still merge.\\\"\\\"\\\"\\n    global_vars = {\\n        \\\"LANGFLOW_REQUEST_VARIABLES\\\": \\\"{not valid json\\\",\\n        \\\"access_token\\\": \\\"raw-tok\\\",\\n    }\\n    flat = build_request_variables_from_global_vars(global_vars)\\n    assert flat == {\\\"access_token\\\": \\\"raw-tok\\\"}\\n\\n\\ndef test_build_request_variables_ignores_non_dict_blob():\\n    \\\"\\\"\\\"A JSON blob that is not an object is ignored; raw keys still merge.\\\"\\\"\\\"\\n    global_vars = {\\n        \\\"LANGFLOW_REQUEST_VARIABLES\\\": json.dumps([\\\"a\\\", \\\"b\\\"]),\\n        \\\"access_token\\\": \\\"raw-tok\\\",\\n    }\\n    flat = build_request_variables_from_global_vars(global_vars)\\n    assert flat == {\\\"access_token\\\": \\\"raw-tok\\\"}\\n\\n\\ndef test_build_request_variables_coerces_structured_blob_values():\\n    \\\"\\\"\\\"JSON null is dropped (never the truthy \\\"None\\\"); dict/list become valid JSON strings.\\\"\\\"\\\"\\n    global_vars = {\\n        \\\"LANGFLOW_REQUEST_VARIABLES\\\": json.dumps(\\n            {\\\"good\\\": \\\"tok\\\", \\\"null_cred\\\": None, \\\"nested\\\": {\\\"a\\\": 1}, \\\"listy\\\": [1, 2]}\\n        ),\\n    }\\n    flat = build_request_variables_from_global_vars(global_vars)\\n    assert flat == {\\\"good\\\": \\\"tok\\\", \\\"nested\\\": '{\\\"a\\\": 1}', \\\"listy\\\": \\\"[1, 2]\\\"}\\n    # Structured values round-trip back through json.loads (a Python repr would not).\\n    assert json.loads(flat[\\\"nested\\\"]) == {\\\"a\\\": 1}\\n\\n\\ndef test_normalize_parsed_variables_coercion_rules():\\n    \\\"\\\"\\\"Scalars -> str, None dropped, dict/list -> valid JSON (round-trippable).\\\"\\\"\\\"\\n    from lfx.services.variable.request_scope import normalize_parsed_variables\\n\\n    out = normalize_parsed_variables({\\\"s\\\": \\\"v\\\", \\\"n\\\": 5, \\\"f\\\": 1.5, \\\"b\\\": True, \\\"drop\\\": None, \\\"d\\\": {\\\"a\\\": 1}, \\\"l\\\": [1, 2]})\\n    assert out == {\\\"s\\\": \\\"v\\\", \\\"n\\\": \\\"5\\\", \\\"f\\\": \\\"1.5\\\", \\\"b\\\": \\\"True\\\", \\\"d\\\": '{\\\"a\\\": 1}', \\\"l\\\": \\\"[1, 2]\\\"}\\n    assert \\\"drop\\\" not in out\\n    assert json.loads(out[\\\"d\\\"]) == {\\\"a\\\": 1}\\n\\n\\ndef test_reset_request_variables_restores_previous_scope():\\n    \\\"\\\"\\\"Nested activate/reset restores the prior scope, not None.\\\"\\\"\\\"\\n    from lfx.services.variable.request_scope import (\\n        activate_request_variables,\\n        get_active_request_variables,\\n        reset_request_variables,\\n    )\\n\\n    outer = activate_request_variables({\\\"A\\\": \\\"1\\\"})\\n    try:\\n        inner = activate_request_variables({\\\"A\\\": \\\"2\\\"})\\n        try:\\n            assert get_active_request_variables() == {\\\"A\\\": \\\"2\\\"}\\n        finally:\\n            reset_request_variables(inner)\\n        assert get_active_request_variables() == {\\\"A\\\": \\\"1\\\"}\\n    finally:\\n        reset_request_variables(outer)\\n    assert get_active_request_variables() is None\\n\\n\\nasync def test_variable_service_reads_active_request_scope():\\n    service = VariableService()\\n    from lfx.services.variable.request_scope import activate_request_variables, reset_request_variables\\n\\n    token = activate_request_variables(\\n        {\\n            \\\"wxo_github_access_token\\\": \\\"tok-123\\\",\\n            \\\"x-langflow-global-var-wxo-github-access-token\\\": \\\"tok-123\\\",\\n        }\\n    )\\n    try:\\n        assert await service.get_variable(\\\"wxo_github_access_token\\\") == \\\"tok-123\\\"\\n        assert await service.get_variable(\\\"access_token\\\") is None\\n    finally:\\n        reset_request_variables(token)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_script_loader.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"efc38e5eff0ce66ca522b1d179abb93ae847a5bec4685242bd1f229f5a781e69\",\"content\":\"\\\"\\\"\\\"Unit tests for LFX CLI script loader.\\\"\\\"\\\"\\n\\nimport sys\\nimport tempfile\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.cli.script_loader import (\\n    _load_module_from_script,\\n    _validate_graph_instance,\\n    extract_message_from_result,\\n    extract_structured_result,\\n    extract_text_from_result,\\n    find_graph_variable,\\n    load_graph_from_script,\\n    temporary_sys_path,\\n)\\n\\n\\n@pytest.fixture\\ndef test_data_dir():\\n    \\\"\\\"\\\"Get the test data directory.\\\"\\\"\\\"\\n    return Path(__file__).parent.parent.parent / \\\"data\\\"\\n\\n\\n@pytest.fixture\\ndef simple_chat_py(test_data_dir):\\n    \\\"\\\"\\\"Path to the simple chat Python script.\\\"\\\"\\\"\\n    return test_data_dir / \\\"simple_chat_no_llm.py\\\"\\n\\n\\nclass TestSysPath:\\n    \\\"\\\"\\\"Test sys.path manipulation utilities.\\\"\\\"\\\"\\n\\n    def test_temporary_sys_path_adds_and_removes(self):\\n        \\\"\\\"\\\"Test that temporary_sys_path correctly adds and removes path.\\\"\\\"\\\"\\n        test_path = \\\"/test/path\\\"\\n        original_path = sys.path.copy()\\n\\n        assert test_path not in sys.path\\n\\n        with temporary_sys_path(test_path):\\n            assert test_path in sys.path\\n            assert sys.path[0] == test_path\\n\\n        assert test_path not in sys.path\\n        assert sys.path == original_path\\n\\n    def test_temporary_sys_path_already_exists(self):\\n        \\\"\\\"\\\"Test temporary_sys_path when path already exists.\\\"\\\"\\\"\\n        test_path = sys.path[0]  # Use existing path\\n        original_path = sys.path.copy()\\n\\n        with temporary_sys_path(test_path):\\n            # Should not add duplicate\\n            assert sys.path == original_path\\n\\n        assert sys.path == original_path\\n\\n    def test_temporary_sys_path_with_exception(self):\\n        \\\"\\\"\\\"Test that path is removed even if exception occurs.\\\"\\\"\\\"\\n        test_path = \\\"/test/exception/path\\\"\\n\\n        def assert_and_raise_exception():\\n            assert test_path in sys.path\\n            msg = \\\"Test exception\\\"\\n            raise ValueError(msg)\\n\\n        # Test that the path is removed even when an exception occurs\\n        with pytest.raises(ValueError, match=\\\"Test exception\\\"), temporary_sys_path(test_path):\\n            assert_and_raise_exception()\\n\\n        assert test_path not in sys.path\\n\\n\\nclass TestModuleLoading:\\n    \\\"\\\"\\\"Test module loading functionality.\\\"\\\"\\\"\\n\\n    def test_load_module_from_script_success(self):\\n        \\\"\\\"\\\"Test successful module loading from script.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"test_var = 'Hello World'\\\\n\\\")\\n            f.write(\\\"def test_func(): return 42\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            module = _load_module_from_script(script_path)\\n            assert hasattr(module, \\\"test_var\\\")\\n            assert module.test_var == \\\"Hello World\\\"\\n            assert hasattr(module, \\\"test_func\\\")\\n            assert module.test_func() == 42\\n        finally:\\n            script_path.unlink()\\n\\n    def test_load_module_from_script_import_error(self):\\n        \\\"\\\"\\\"Test module loading with import error.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"import non_existent_module\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            with pytest.raises(ImportError):\\n                _load_module_from_script(script_path)\\n        finally:\\n            script_path.unlink()\\n\\n    def test_load_module_from_script_syntax_error(self):\\n        \\\"\\\"\\\"Test module loading with syntax error.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"def broken_func(\\\\n\\\")  # Invalid syntax\\n            script_path = Path(f.name)\\n\\n        try:\\n            with pytest.raises(SyntaxError):\\n                _load_module_from_script(script_path)\\n        finally:\\n            script_path.unlink()\\n\\n\\nclass TestGraphValidation:\\n    \\\"\\\"\\\"Test graph validation functionality.\\\"\\\"\\\"\\n\\n    def test_validate_graph_instance_valid(self):\\n        \\\"\\\"\\\"Test validation of valid graph instance.\\\"\\\"\\\"\\n        from lfx.components.input_output import ChatInput, ChatOutput\\n        from lfx.graph import Graph\\n\\n        # Create a real graph with ChatInput and ChatOutput\\n        chat_input = ChatInput()\\n        chat_output = ChatOutput().set(input_value=chat_input.message_response)\\n        graph = Graph(chat_input, chat_output)\\n\\n        result = _validate_graph_instance(graph)\\n        assert result == graph\\n\\n    def test_validate_graph_instance_wrong_type(self):\\n        \\\"\\\"\\\"Test validation with wrong type.\\\"\\\"\\\"\\n        not_a_graph = {\\\"not\\\": \\\"a graph\\\"}\\n\\n        with pytest.raises(TypeError, match=\\\"Graph object is not a LFX Graph instance\\\"):\\n            _validate_graph_instance(not_a_graph)\\n\\n    def test_validate_graph_instance_missing_chat_input(self):\\n        \\\"\\\"\\\"Test validation with missing ChatInput.\\\"\\\"\\\"\\n        from lfx.components.input_output import ChatOutput\\n        from lfx.graph import Graph\\n\\n        # Create a graph with only ChatOutput, no ChatInput\\n        chat_output = ChatOutput()\\n        graph = Graph(start=chat_output, end=chat_output)\\n\\n        with pytest.raises(ValueError, match=\\\"Graph does not contain any ChatInput component\\\"):\\n            _validate_graph_instance(graph)\\n\\n    def test_validate_graph_instance_missing_chat_output(self):\\n        \\\"\\\"\\\"Test validation with missing ChatOutput.\\\"\\\"\\\"\\n        from lfx.components.input_output import ChatInput\\n        from lfx.graph import Graph\\n\\n        # Create a graph with only ChatInput, no ChatOutput\\n        chat_input = ChatInput()\\n        graph = Graph(start=chat_input, end=chat_input)\\n\\n        with pytest.raises(ValueError, match=\\\"Graph does not contain any ChatOutput component\\\"):\\n            _validate_graph_instance(graph)\\n\\n\\nclass TestLoadGraphFromScript:\\n    \\\"\\\"\\\"Test loading graph from script functionality.\\\"\\\"\\\"\\n\\n    async def test_load_graph_from_script_success(self, simple_chat_py):\\n        \\\"\\\"\\\"Test successful graph loading from script with real Graph object.\\\"\\\"\\\"\\n        # Use the existing test data file\\n        graph = await load_graph_from_script(simple_chat_py)\\n\\n        # Verify it's a real Graph instance\\n        from lfx.graph import Graph\\n\\n        assert isinstance(graph, Graph)\\n\\n        # Verify it has the expected components\\n        component_names = {v.custom_component.__class__.__name__ for v in graph.vertices}\\n        assert \\\"ChatInput\\\" in component_names\\n        assert \\\"ChatOutput\\\" in component_names\\n\\n    @pytest.mark.parametrize(\\n        (\\\"blocked_component_keys\\\", \\\"expected_blocked\\\"),\\n        [\\n            pytest.param({\\\"OtherComponent\\\"}, False, id=\\\"unrelated-blocklist-allows-graph\\\"),\\n            pytest.param({\\\"Chat Input\\\"}, True, id=\\\"legacy-alias-blocks-graph\\\"),\\n        ],\\n    )\\n    async def test_active_catalog_policy_warms_cold_identity_cache_before_validation(\\n        self,\\n        blocked_component_keys,\\n        expected_blocked,\\n    ):\\n        \\\"\\\"\\\"Script graphs must resolve active policy aliases on the first cold-cache load.\\\"\\\"\\\"\\n        from lfx.components.input_output import ChatInput, ChatOutput\\n        from lfx.graph import Graph\\n        from lfx.interface import components as components_module\\n        from lfx.services.catalog_policy import CatalogPolicySnapshot\\n\\n        chat_input = ChatInput()\\n        chat_output = ChatOutput().set(input_value=chat_input.message_response)\\n        graph = Graph(chat_input, chat_output)\\n        graph.raw_graph_data = {\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"chat-input\\\", \\\"data\\\": {\\\"id\\\": \\\"chat-input\\\", \\\"type\\\": \\\"ChatInput\\\"}}],\\n            \\\"edges\\\": [],\\n        }\\n        cache = components_module.ComponentCache()\\n        settings_service = SimpleNamespace(settings=SimpleNamespace(allow_custom_components=True))\\n        catalog_service = SimpleNamespace(\\n            snapshot=CatalogPolicySnapshot(blocked_component_keys=blocked_component_keys),\\n        )\\n        builtins = {\\n            \\\"components\\\": {\\n                \\\"input_output\\\": {\\n                    \\\"ChatInput\\\": {\\n                        \\\"display_name\\\": \\\"Chat Input\\\",\\n                        \\\"template\\\": {\\\"_type\\\": \\\"Component\\\"},\\n                    }\\n                }\\n            }\\n        }\\n\\n        with (\\n            patch(\\\"lfx.cli.script_loader._load_module_from_script\\\", return_value=SimpleNamespace(graph=graph)),\\n            patch.object(components_module, \\\"component_cache\\\", cache),\\n            patch.object(\\n                components_module,\\n                \\\"import_langflow_components\\\",\\n                new=AsyncMock(return_value=builtins),\\n            ) as load,\\n            patch.object(components_module, \\\"_determine_loading_strategy\\\", new=AsyncMock(return_value={})),\\n            patch.object(components_module, \\\"import_extension_components\\\", new=AsyncMock(return_value={})),\\n            patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=settings_service),\\n            patch(\\\"lfx.services.deps.get_catalog_policy_service\\\", return_value=catalog_service),\\n        ):\\n            if expected_blocked:\\n                with pytest.raises(RuntimeError, match=\\\"catalog policy blocks components: ChatInput\\\"):\\n                    await load_graph_from_script(Path(\\\"cold-cache-script.py\\\"))\\n            else:\\n                assert await load_graph_from_script(Path(\\\"cold-cache-script.py\\\")) is graph\\n\\n        load.assert_awaited_once_with(settings_service, None)\\n        assert cache.all_types_ready\\n        assert cache.component_identity_index is not None\\n\\n    async def test_load_graph_from_script_no_graph_variable(self):\\n        \\\"\\\"\\\"Test error when script has no graph variable.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"other_var = 123\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            with pytest.raises(RuntimeError, match=\\\"No 'graph' variable or 'get_graph\\\\\\\\(\\\\\\\\)' function found\\\"):\\n                await load_graph_from_script(script_path)\\n        finally:\\n            script_path.unlink()\\n\\n    async def test_load_graph_from_script_import_error(self):\\n        \\\"\\\"\\\"Test error handling for import errors.\\\"\\\"\\\"\\n        script_path = Path(\\\"/non/existent/script.py\\\")\\n\\n        with pytest.raises(RuntimeError, match=\\\"Error executing script\\\"):\\n            await load_graph_from_script(script_path)\\n\\n    async def test_load_graph_from_script_with_async_get_graph(self):\\n        \\\"\\\"\\\"Test loading graph from script with async get_graph function.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"from lfx.components.input_output import ChatInput, ChatOutput\\\\n\\\")\\n            f.write(\\\"from lfx.graph import Graph\\\\n\\\")\\n            f.write(\\\"\\\\n\\\")\\n            f.write(\\\"async def get_graph():\\\\n\\\")\\n            f.write(\\\"    chat_input = ChatInput()\\\\n\\\")\\n            f.write(\\\"    chat_output = ChatOutput().set(input_value=chat_input.message_response)\\\\n\\\")\\n            f.write(\\\"    return Graph(chat_input, chat_output)\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            graph = await load_graph_from_script(script_path)\\n\\n            # Verify it's a real Graph instance\\n            from lfx.graph import Graph\\n\\n            assert isinstance(graph, Graph)\\n\\n            # Verify it has the expected components\\n            component_names = {v.custom_component.__class__.__name__ for v in graph.vertices}\\n            assert \\\"ChatInput\\\" in component_names\\n            assert \\\"ChatOutput\\\" in component_names\\n        finally:\\n            script_path.unlink()\\n\\n    async def test_load_graph_from_script_with_sync_get_graph(self):\\n        \\\"\\\"\\\"Test loading graph from script with sync get_graph function.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"from lfx.components.input_output import ChatInput, ChatOutput\\\\n\\\")\\n            f.write(\\\"from lfx.graph import Graph\\\\n\\\")\\n            f.write(\\\"\\\\n\\\")\\n            f.write(\\\"def get_graph():\\\\n\\\")\\n            f.write(\\\"    chat_input = ChatInput()\\\\n\\\")\\n            f.write(\\\"    chat_output = ChatOutput().set(input_value=chat_input.message_response)\\\\n\\\")\\n            f.write(\\\"    return Graph(chat_input, chat_output)\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            graph = await load_graph_from_script(script_path)\\n\\n            # Verify it's a real Graph instance\\n            from lfx.graph import Graph\\n\\n            assert isinstance(graph, Graph)\\n\\n            # Verify it has the expected components\\n            component_names = {v.custom_component.__class__.__name__ for v in graph.vertices}\\n            assert \\\"ChatInput\\\" in component_names\\n            assert \\\"ChatOutput\\\" in component_names\\n        finally:\\n            script_path.unlink()\\n\\n\\nclass TestResultExtraction:\\n    \\\"\\\"\\\"Test result extraction utilities.\\\"\\\"\\\"\\n\\n    def test_extract_message_from_result_success(self):\\n        \\\"\\\"\\\"Test extracting message from result.\\\"\\\"\\\"\\n        from lfx.graph.schema import ResultData\\n        from lfx.schema.message import Message\\n\\n        # Create a real Message object\\n        message = Message(text=\\\"Hello\\\")\\n\\n        # Create ResultData with the message\\n        result_data = ResultData(\\n            results={\\\"message\\\": message}, component_display_name=\\\"Chat Output\\\", component_id=\\\"test-123\\\"\\n        )\\n\\n        # Create a minimal mock for the vertex structure\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_result.result_dict = result_data\\n\\n        results = [mock_result]\\n\\n        message_json = extract_message_from_result(results)\\n        assert \\\"Hello\\\" in message_json\\n        assert \\\"text\\\" in message_json\\n\\n    def test_extract_message_from_result_no_chat_output(self):\\n        \\\"\\\"\\\"Test extraction when no Chat Output found.\\\"\\\"\\\"\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Other Component\\\"\\n\\n        results = [mock_result]\\n\\n        message = extract_message_from_result(results)\\n        assert message == \\\"No response generated\\\"\\n\\n    def test_extract_text_from_result_success(self):\\n        \\\"\\\"\\\"Test extracting text content from result.\\\"\\\"\\\"\\n        from lfx.graph.schema import ResultData\\n        from lfx.schema.message import Message\\n\\n        # Create a real Message object\\n        message = Message(text=\\\"Hello World\\\")\\n\\n        # Create ResultData with the message\\n        result_data = ResultData(\\n            results={\\\"message\\\": message}, component_display_name=\\\"Chat Output\\\", component_id=\\\"test-123\\\"\\n        )\\n\\n        # Create a minimal mock for the vertex structure\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_result.result_dict = result_data\\n\\n        results = [mock_result]\\n\\n        text = extract_text_from_result(results)\\n        assert text == \\\"Hello World\\\"\\n\\n    def test_extract_text_from_result_no_text_attribute(self):\\n        \\\"\\\"\\\"Test extraction when message has no text attribute.\\\"\\\"\\\"\\n        from lfx.graph.schema import ResultData\\n\\n        # Use a plain string as message\\n        result_data = ResultData(\\n            results={\\\"message\\\": \\\"Plain string message\\\"}, component_display_name=\\\"Chat Output\\\", component_id=\\\"test-123\\\"\\n        )\\n\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_result.result_dict = result_data\\n\\n        results = [mock_result]\\n\\n        text = extract_text_from_result(results)\\n        assert text == \\\"Plain string message\\\"\\n\\n    def test_extract_text_from_result_with_dict_message(self):\\n        \\\"\\\"\\\"Test extraction when message is a dict with text key.\\\"\\\"\\\"\\n        from lfx.graph.schema import ResultData\\n\\n        # Use a dict as message\\n        result_data = ResultData(\\n            results={\\\"message\\\": {\\\"text\\\": \\\"Dict message text\\\"}},\\n            component_display_name=\\\"Chat Output\\\",\\n            component_id=\\\"test-123\\\",\\n        )\\n\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_result.result_dict = result_data\\n\\n        results = [mock_result]\\n\\n        text = extract_text_from_result(results)\\n        assert text == \\\"Dict message text\\\"\\n\\n    def test_extract_structured_result_success(self):\\n        \\\"\\\"\\\"Test extracting structured result data.\\\"\\\"\\\"\\n        from lfx.graph.schema import ResultData\\n        from lfx.schema.message import Message\\n\\n        # Create a real Message object\\n        message = Message(text=\\\"Test message\\\")\\n\\n        # Create ResultData with the message\\n        result_data = ResultData(\\n            results={\\\"message\\\": message}, component_display_name=\\\"Chat Output\\\", component_id=\\\"vertex-123\\\"\\n        )\\n\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_result.vertex.id = \\\"vertex-123\\\"\\n        mock_result.result_dict = result_data\\n\\n        results = [mock_result]\\n\\n        structured = extract_structured_result(results, extract_text=True)\\n\\n        assert structured == {\\n            \\\"result\\\": \\\"Test message\\\",\\n            \\\"type\\\": \\\"message\\\",\\n            \\\"component\\\": \\\"Chat Output\\\",\\n            \\\"component_id\\\": \\\"vertex-123\\\",\\n            \\\"success\\\": True,\\n        }\\n\\n    def test_extract_structured_result_no_text_extraction(self):\\n        \\\"\\\"\\\"Test structured extraction without text extraction.\\\"\\\"\\\"\\n        from lfx.graph.schema import ResultData\\n        from lfx.schema.message import Message\\n\\n        # Create a real Message object\\n        message = Message(text=\\\"Test message\\\")\\n\\n        # Create ResultData with the message\\n        result_data = ResultData(\\n            results={\\\"message\\\": message}, component_display_name=\\\"Chat Output\\\", component_id=\\\"vertex-123\\\"\\n        )\\n\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_result.vertex.id = \\\"vertex-123\\\"\\n        mock_result.result_dict = result_data\\n\\n        results = [mock_result]\\n\\n        structured = extract_structured_result(results, extract_text=False)\\n\\n        assert structured[\\\"result\\\"] == message\\n        assert structured[\\\"type\\\"] == \\\"message\\\"\\n        assert structured[\\\"component\\\"] == \\\"Chat Output\\\"\\n        assert structured[\\\"success\\\"] is True\\n\\n    def test_extract_structured_result_extraction_error(self):\\n        \\\"\\\"\\\"Test structured extraction with error.\\\"\\\"\\\"\\n        from lfx.graph.schema import ResultData\\n\\n        # Create a custom message class that has text attribute but raises when accessed\\n        class ErrorMessage:\\n            @property\\n            def text(self):\\n                msg = \\\"No text available\\\"\\n                raise AttributeError(msg)\\n\\n            def __str__(self):\\n                return \\\"ErrorMessage instance\\\"\\n\\n        # Create ResultData with the error message\\n        result_data = ResultData(\\n            results={\\\"message\\\": ErrorMessage()}, component_display_name=\\\"Chat Output\\\", component_id=\\\"vertex-123\\\"\\n        )\\n\\n        mock_result = MagicMock()\\n        mock_result.vertex.custom_component.display_name = \\\"Chat Output\\\"\\n        mock_result.vertex.id = \\\"vertex-123\\\"\\n        mock_result.result_dict = result_data\\n\\n        results = [mock_result]\\n\\n        structured = extract_structured_result(results, extract_text=True)\\n\\n        # Since hasattr returns False for properties that raise AttributeError,\\n        # the code returns the message object itself (no warning)\\n        assert structured[\\\"success\\\"] is True\\n        assert \\\"warning\\\" not in structured  # No warning because hasattr is False\\n        assert structured[\\\"result\\\"] == result_data.results[\\\"message\\\"]  # Returns the ErrorMessage instance\\n        assert structured[\\\"type\\\"] == \\\"message\\\"\\n        assert structured[\\\"component\\\"] == \\\"Chat Output\\\"\\n\\n    def test_extract_structured_result_no_results(self):\\n        \\\"\\\"\\\"Test structured extraction with no results.\\\"\\\"\\\"\\n        results = []\\n\\n        structured = extract_structured_result(results)\\n\\n        assert structured == {\\n            \\\"text\\\": \\\"No response generated\\\",\\n            \\\"type\\\": \\\"error\\\",\\n            \\\"success\\\": False,\\n        }\\n\\n\\nclass TestFindGraphVariable:\\n    \\\"\\\"\\\"Test AST-based graph variable finding.\\\"\\\"\\\"\\n\\n    def test_find_graph_variable_function_call(self):\\n        \\\"\\\"\\\"Test finding graph variable with function call.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"from lfx import Graph\\\\n\\\")\\n            f.write(\\\"\\\\n\\\")\\n            f.write(\\\"graph = Graph(nodes=[], edges=[])\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            result = find_graph_variable(script_path)\\n            assert result is not None\\n            assert result[\\\"type\\\"] == \\\"function_call\\\"\\n            assert result[\\\"function\\\"] == \\\"Graph\\\"\\n            assert result[\\\"line_number\\\"] == 3\\n            assert \\\"graph = Graph\\\" in result[\\\"source_line\\\"]\\n        finally:\\n            script_path.unlink()\\n\\n    def test_find_graph_variable_method_call(self):\\n        \\\"\\\"\\\"Test finding graph variable with method call.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"from lfx import Graph\\\\n\\\")\\n            f.write(\\\"\\\\n\\\")\\n            f.write(\\\"graph = Graph.from_payload(data)\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            result = find_graph_variable(script_path)\\n            assert result is not None\\n            assert result[\\\"type\\\"] == \\\"function_call\\\"\\n            assert result[\\\"function\\\"] == \\\"Graph.from_payload\\\"\\n            assert result[\\\"line_number\\\"] == 3\\n        finally:\\n            script_path.unlink()\\n\\n    def test_find_graph_variable_assignment(self):\\n        \\\"\\\"\\\"Test finding graph variable with simple assignment.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"existing_graph = get_graph()\\\\n\\\")\\n            f.write(\\\"graph = existing_graph\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            result = find_graph_variable(script_path)\\n            assert result is not None\\n            assert result[\\\"type\\\"] == \\\"assignment\\\"\\n            assert result[\\\"line_number\\\"] == 2\\n            assert \\\"graph = existing_graph\\\" in result[\\\"source_line\\\"]\\n        finally:\\n            script_path.unlink()\\n\\n    def test_find_graph_variable_not_found(self):\\n        \\\"\\\"\\\"Test when no graph variable is found.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"other_var = 123\\\\n\\\")\\n            f.write(\\\"another_var = 'test'\\\\n\\\")\\n            script_path = Path(f.name)\\n\\n        try:\\n            result = find_graph_variable(script_path)\\n            assert result is None\\n        finally:\\n            script_path.unlink()\\n\\n    def test_find_graph_variable_syntax_error(self):\\n        \\\"\\\"\\\"Test handling of syntax errors.\\\"\\\"\\\"\\n        with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n            f.write(\\\"def broken(\\\\n\\\")  # Invalid syntax\\n            script_path = Path(f.name)\\n\\n        try:\\n            with patch(\\\"typer.echo\\\") as mock_echo:\\n                result = find_graph_variable(script_path)\\n                assert result is None\\n                mock_echo.assert_called_once()\\n                assert \\\"Invalid Python syntax\\\" in mock_echo.call_args[0][0]\\n        finally:\\n            script_path.unlink()\\n\\n    def test_find_graph_variable_file_not_found(self):\\n        \\\"\\\"\\\"Test handling of missing file.\\\"\\\"\\\"\\n        script_path = Path(\\\"/non/existent/file.py\\\")\\n\\n        with patch(\\\"typer.echo\\\") as mock_echo:\\n            result = find_graph_variable(script_path)\\n            assert result is None\\n            mock_echo.assert_called_once()\\n            assert \\\"not found\\\" in mock_echo.call_args[0][0]\\n\\n\\nclass TestIntegrationWithRealFlows:\\n    \\\"\\\"\\\"Integration tests using real flows and minimal mocking.\\\"\\\"\\\"\\n\\n    async def test_load_and_validate_real_script(self, simple_chat_py):\\n        \\\"\\\"\\\"Test loading and validating a real script file.\\\"\\\"\\\"\\n        # Load the real graph from the script\\n        graph = await load_graph_from_script(simple_chat_py)\\n\\n        # Verify it's a real Graph\\n        from lfx.graph import Graph\\n\\n        assert isinstance(graph, Graph)\\n\\n        # Verify components\\n        component_types = {v.custom_component.__class__.__name__ for v in graph.vertices}\\n        assert \\\"ChatInput\\\" in component_types\\n        assert \\\"ChatOutput\\\" in component_types\\n\\n    async def test_execute_real_flow_with_results(self, simple_chat_py):\\n        \\\"\\\"\\\"Test executing a real flow and extracting results.\\\"\\\"\\\"\\n        # Load the real graph\\n        graph = await load_graph_from_script(simple_chat_py)\\n\\n        # Execute the graph with real input\\n        from lfx.graph.schema import RunOutputs\\n\\n        # Start the graph execution\\n        results = [result async for result in graph.async_start(inputs={\\\"input_value\\\": \\\"Test message\\\"})]\\n\\n        # Extract results using our functions\\n        if isinstance(results, RunOutputs) and results.outputs:\\n            # Convert RunOutputs to the format expected by extract functions\\n            result_list = []\\n            for output in results.outputs:\\n                mock_result = MagicMock()\\n                mock_result.vertex.custom_component.display_name = output.component_display_name\\n                mock_result.vertex.id = output.component_id\\n                mock_result.result_dict = output\\n                result_list.append(mock_result)\\n\\n            # Test extraction functions with real results\\n            text = extract_text_from_result(result_list)\\n            assert \\\"Test message\\\" in text\\n\\n            message_json = extract_message_from_result(result_list)\\n            assert \\\"Test message\\\" in message_json\\n\\n            structured = extract_structured_result(result_list)\\n            assert structured[\\\"success\\\"] is True\\n            assert \\\"Test message\\\" in str(structured[\\\"result\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/cli/test_serve.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5b77fb56ad6b93fd410d5db9bae722c7f390550aed6750c69fb66b1393f3304b\",\"content\":\"\\\"\\\"\\\"Tests for LFX serve command.\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport tempfile\\nfrom pathlib import Path\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom fastapi.testclient import TestClient\\nfrom lfx.cli.common import (\\n    flow_id_from_path,\\n    get_api_key,\\n    get_best_access_host,\\n    get_free_port,\\n    is_port_in_use,\\n)\\nfrom lfx.cli.serve_app import FlowMeta, create_multi_serve_app\\n\\n\\ndef test_is_port_in_use():\\n    \\\"\\\"\\\"Test port availability checking.\\\"\\\"\\\"\\n    # Port 0 should always be available (OS assigns)\\n    assert not is_port_in_use(0)\\n\\n    # Very high ports are likely available\\n    assert not is_port_in_use(65123)\\n\\n\\ndef test_get_free_port():\\n    \\\"\\\"\\\"Test finding a free port.\\\"\\\"\\\"\\n    port = get_free_port(8000)\\n    assert 8000 <= port < 65535\\n    assert not is_port_in_use(port)\\n\\n\\ndef test_get_best_access_host():\\n    \\\"\\\"\\\"Test host resolution for display.\\\"\\\"\\\"\\n    assert get_best_access_host(\\\"0.0.0.0\\\") == \\\"localhost\\\"\\n    assert get_best_access_host(\\\"\\\") == \\\"localhost\\\"\\n    assert get_best_access_host(\\\"127.0.0.1\\\") == \\\"127.0.0.1\\\"\\n    assert get_best_access_host(\\\"example.com\\\") == \\\"example.com\\\"\\n\\n\\ndef test_get_api_key_missing():\\n    \\\"\\\"\\\"Test API key retrieval when not set.\\\"\\\"\\\"\\n    with (\\n        patch.dict(os.environ, {}, clear=True),\\n        pytest.raises(\\n            ValueError,\\n            match=\\\"LANGFLOW_API_KEY environment variable is not set\\\",\\n        ),\\n    ):\\n        get_api_key()\\n\\n\\ndef test_get_api_key_present():\\n    \\\"\\\"\\\"Test API key retrieval when set.\\\"\\\"\\\"\\n    with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key-123\\\"}):  # pragma: allowlist secret\\n        assert get_api_key() == \\\"test-key-123\\\"\\n\\n\\ndef test_flow_id_from_path():\\n    \\\"\\\"\\\"Test deterministic flow ID generation.\\\"\\\"\\\"\\n    root = Path(\\\"/tmp/flows\\\")\\n    path1 = root / \\\"flow1.json\\\"\\n    path2 = root / \\\"subdir\\\" / \\\"flow2.json\\\"\\n\\n    # Same path should always generate same ID\\n    id1a = flow_id_from_path(path1, root)\\n    id1b = flow_id_from_path(path1, root)\\n    assert id1a == id1b\\n\\n    # Different paths should generate different IDs\\n    id2 = flow_id_from_path(path2, root)\\n    assert id1b != id2\\n\\n\\n@pytest.fixture\\ndef mock_graph():\\n    \\\"\\\"\\\"Create a mock graph for testing.\\\"\\\"\\\"\\n    graph = MagicMock()\\n    graph.nodes = {\\\"node1\\\": MagicMock()}\\n    graph.prepare = MagicMock()\\n    graph.arun = AsyncMock(return_value=[])\\n    return graph\\n\\n\\n@pytest.fixture\\ndef test_flow_meta():\\n    \\\"\\\"\\\"Create test flow metadata.\\\"\\\"\\\"\\n    return FlowMeta(\\n        id=\\\"test-flow-id\\\",\\n        relative_path=\\\"test.json\\\",\\n        title=\\\"Test Flow\\\",\\n        description=\\\"A test flow\\\",\\n    )\\n\\n\\ndef test_create_multi_serve_app_unknown_flow_id_returns_404(mock_graph, test_flow_meta):\\n    from lfx.cli.serve_app import FlowRegistry\\n\\n    registry = FlowRegistry()\\n    registry.add(mock_graph, test_flow_meta)\\n\\n    with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}):  # pragma: allowlist secret\\n        app = create_multi_serve_app(registry=registry)\\n        client = TestClient(app)\\n\\n        response = client.get(\\\"/flows/does-not-exist/info\\\", headers={\\\"x-api-key\\\": \\\"test-key\\\"})\\n        assert response.status_code == 404\\n\\n        response = client.post(\\n            \\\"/flows/does-not-exist/run\\\",\\n            json={\\\"input_value\\\": \\\"test\\\"},\\n            headers={\\\"x-api-key\\\": \\\"test-key\\\"},\\n        )\\n        assert response.status_code == 404\\n\\n\\ndef test_serve_command_json_file():\\n    \\\"\\\"\\\"Test serve command with JSON file input.\\\"\\\"\\\"\\n    # Create a temporary JSON flow file\\n    flow_data = {\\n        \\\"nodes\\\": [],\\n        \\\"edges\\\": [],\\n    }\\n\\n    with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".json\\\", delete=False) as f:\\n        json.dump(flow_data, f)\\n        temp_path = f.name\\n\\n    try:\\n        # Mock the necessary dependencies\\n        with (\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\") as mock_load,\\n            patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        ):\\n            import typer\\n            from lfx.cli.commands import serve_command\\n            from typer.testing import CliRunner\\n\\n            # Create a mock graph\\n            mock_graph = MagicMock()\\n            mock_graph.prepare = MagicMock()\\n            # Mock nodes as a dictionary for graph analysis\\n            mock_node = MagicMock()\\n            mock_node.data = {\\n                \\\"type\\\": \\\"TestComponent\\\",\\n                \\\"display_name\\\": \\\"Test Component\\\",\\n                \\\"description\\\": \\\"A test component\\\",\\n                \\\"template\\\": {},\\n            }\\n            mock_graph.nodes = {\\\"node1\\\": mock_node}\\n\\n            # Mock edges as a list\\n            mock_edge = MagicMock()\\n            mock_edge.source = \\\"node1\\\"\\n            mock_edge.target = \\\"node2\\\"\\n            mock_graph.edges = [mock_edge]\\n            mock_load.return_value = mock_graph\\n\\n            # Create CLI app\\n            app = typer.Typer()\\n            app.command()(serve_command)\\n\\n            runner = CliRunner()\\n            result = runner.invoke(app, [temp_path, \\\"--verbose\\\"])\\n\\n            assert result.exit_code == 0, result.stdout\\n\\n            # Should start the server\\n            assert mock_uvicorn.called\\n            mock_load.assert_called_once()\\n\\n            # Check that the mock was called with the parsed JSON dict (not a path)\\n            args, _kwargs = mock_load.call_args\\n            assert isinstance(args[0], dict)\\n\\n    finally:\\n        Path(temp_path).unlink()\\n\\n\\ndef test_serve_command_inline_json():\\n    \\\"\\\"\\\"Test serve command with inline JSON.\\\"\\\"\\\"\\n    flow_json = '{\\\"nodes\\\": [], \\\"edges\\\": []}'\\n\\n    with (\\n        patch(\\\"lfx.cli.commands.load_flow_from_json\\\") as mock_load,\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n    ):\\n        import typer\\n        from lfx.cli.commands import serve_command\\n        from typer.testing import CliRunner\\n\\n        # Create a mock graph\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.nodes = {}\\n        mock_load.return_value = mock_graph\\n\\n        # Create CLI app\\n        app = typer.Typer()\\n        app.command()(serve_command)\\n\\n        runner = CliRunner()\\n        result = runner.invoke(app, [\\\"--flow-json\\\", flow_json, \\\"--verbose\\\"])\\n\\n        assert result.exit_code == 0, result.stdout\\n\\n        # Should start the server\\n        assert mock_uvicorn.called\\n        mock_load.assert_called_once()\\n\\n        # Check that the mock was called with the parsed JSON dict (not a temp file path)\\n        args, _kwargs = mock_load.call_args\\n        assert isinstance(args[0], dict)\\n\\n\\ndef test_serve_command_env_file_overrides_shell_environment(tmp_path):\\n    \\\"\\\"\\\"An explicit --env-file must take precedence over shell environment variables.\\\"\\\"\\\"\\n    env_file = tmp_path / \\\".env\\\"\\n    env_file.write_text(\\\"LANGFLOW_API_KEY=from-env-file\\\\n\\\")  # pragma: allowlist secret\\n    flow_json = '{\\\"nodes\\\": [], \\\"edges\\\": []}'\\n\\n    with (\\n        patch(\\\"lfx.cli.commands.load_flow_from_json\\\") as mock_load,\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\"),\\n        patch(\\\"lfx.cli.commands.is_port_in_use\\\", return_value=False),\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"from-shell\\\"}),  # pragma: allowlist secret\\n    ):\\n        import typer\\n        from lfx.cli.commands import serve_command\\n        from typer.testing import CliRunner\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.nodes = {}\\n        mock_load.return_value = mock_graph\\n\\n        app = typer.Typer()\\n        app.command()(serve_command)\\n\\n        result = CliRunner().invoke(app, [\\\"--flow-json\\\", flow_json, \\\"--env-file\\\", str(env_file)])\\n\\n        assert result.exit_code == 0, result.stdout\\n        assert os.environ[\\\"LANGFLOW_API_KEY\\\"] == \\\"from-env-file\\\"  # pragma: allowlist secret\\n\\n\\nclass TestBuildRegistryFromDirectory:\\n    def test_loads_all_json_files(self, tmp_path):\\n        import asyncio\\n\\n        from lfx.cli.commands import build_registry_from_directory\\n\\n        flow_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        (tmp_path / \\\"a.json\\\").write_text(json.dumps(flow_data))\\n        (tmp_path / \\\"b.json\\\").write_text(json.dumps(flow_data))\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.flow_id = None\\n\\n        with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n            registry = asyncio.run(build_registry_from_directory(tmp_path, lambda _: None, check_variables=False))\\n\\n        assert len(registry) == 2\\n\\n    def test_empty_directory_raises(self, tmp_path):\\n        import asyncio\\n\\n        from lfx.cli.commands import build_registry_from_directory\\n\\n        with pytest.raises(ValueError, match=r\\\"No \\\\.json files found\\\"):\\n            asyncio.run(build_registry_from_directory(tmp_path, lambda _: None, check_variables=False))\\n\\n    def test_non_json_files_ignored(self, tmp_path):\\n        import asyncio\\n\\n        from lfx.cli.commands import build_registry_from_directory\\n\\n        (tmp_path / \\\"notes.txt\\\").write_text(\\\"ignore me\\\")\\n        flow_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        (tmp_path / \\\"flow.json\\\").write_text(json.dumps(flow_data))\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.flow_id = None\\n\\n        with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n            registry = asyncio.run(build_registry_from_directory(tmp_path, lambda _: None, check_variables=False))\\n\\n        assert len(registry) == 1\\n\\n    def test_failed_file_raises_with_filename(self, tmp_path):\\n        import asyncio\\n\\n        from lfx.cli.commands import build_registry_from_directory\\n\\n        (tmp_path / \\\"bad.json\\\").write_text('{\\\"nodes\\\": [], \\\"edges\\\": []}')\\n\\n        with (\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", side_effect=ValueError(\\\"corrupt\\\")),\\n            pytest.raises(ValueError, match=r\\\"bad\\\\.json\\\"),\\n        ):\\n            asyncio.run(build_registry_from_directory(tmp_path, lambda _: None, check_variables=False))\\n\\n\\nclass TestBuildRegistryFromPaths:\\n    def test_loads_explicit_paths(self, tmp_path):\\n        import asyncio\\n\\n        from lfx.cli.commands import build_registry_from_paths\\n\\n        flow_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        p1 = tmp_path / \\\"flow1.json\\\"\\n        p2 = tmp_path / \\\"flow2.json\\\"\\n        p1.write_text(json.dumps(flow_data))\\n        p2.write_text(json.dumps(flow_data))\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.flow_id = None\\n\\n        with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n            registry = asyncio.run(build_registry_from_paths([p1, p2], lambda _: None, check_variables=False))\\n\\n        assert len(registry) == 2\\n\\n    def test_failed_path_raises_with_filename(self, tmp_path):\\n        import asyncio\\n\\n        from lfx.cli.commands import build_registry_from_paths\\n\\n        p = tmp_path / \\\"bad.json\\\"\\n        p.write_text('{\\\"nodes\\\": [], \\\"edges\\\": []}')\\n\\n        with (\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", side_effect=ValueError(\\\"oops\\\")),\\n            pytest.raises(ValueError, match=r\\\"bad\\\\.json\\\"),\\n        ):\\n            asyncio.run(build_registry_from_paths([p], lambda _: None, check_variables=False))\\n\\n    def test_same_filename_in_different_dirs_gets_distinct_ids(self, tmp_path):\\n        \\\"\\\"\\\"Regression: lfx serve a/flow.json b/flow.json must not collide on ID.\\\"\\\"\\\"\\n        import asyncio\\n\\n        from lfx.cli.commands import build_registry_from_paths\\n\\n        dir_a = tmp_path / \\\"a\\\"\\n        dir_b = tmp_path / \\\"b\\\"\\n        dir_a.mkdir()\\n        dir_b.mkdir()\\n        flow_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        p1 = dir_a / \\\"flow.json\\\"\\n        p2 = dir_b / \\\"flow.json\\\"\\n        p1.write_text(json.dumps(flow_data))\\n        p2.write_text(json.dumps(flow_data))\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.flow_id = None\\n\\n        with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n            registry = asyncio.run(build_registry_from_paths([p1, p2], lambda _: None, check_variables=False))\\n\\n        assert len(registry) == 2, \\\"both flows must be registered with distinct IDs\\\"\\n\\n\\nclass TestBuildServeRegistryTempCleanup:\\n    \\\"\\\"\\\"``_build_serve_registry`` owns the temp file until it hands the path back.\\n\\n    ``serve_command`` only learns the path from a successful return, so any exit that\\n    skips that return has to unlink the staged flow itself or it is orphaned in the\\n    system temp directory.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _build(**overrides):\\n        import asyncio\\n\\n        from lfx.cli.commands import _build_serve_registry\\n\\n        kwargs = {\\n            \\\"script_paths\\\": None,\\n            \\\"flow_json\\\": None,\\n            \\\"stdin\\\": False,\\n            \\\"check_variables\\\": False,\\n            \\\"no_env_fallback\\\": False,\\n            \\\"flow_store\\\": MagicMock(),\\n            \\\"verbose_print\\\": lambda _: None,\\n        }\\n        kwargs.update(overrides)\\n        return asyncio.run(_build_serve_registry(**kwargs))\\n\\n    def test_inline_flow_removes_temp_file_when_registry_build_fails(self, tmp_path, monkeypatch):\\n        import typer\\n\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(tmp_path))\\n\\n        with (\\n            patch(\\\"lfx.cli.commands.build_registry_from_paths\\\", new=AsyncMock(side_effect=ValueError(\\\"invalid flow\\\"))),\\n            pytest.raises(typer.Exit),\\n        ):\\n            self._build(flow_json=\\\"{}\\\")\\n\\n        assert list(tmp_path.iterdir()) == []\\n\\n    def test_inline_flow_removes_temp_file_when_build_fails_unexpectedly(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Cleanup can't hinge on ValueError \u2014 a Ctrl-C mid-load orphans the file too.\\\"\\\"\\\"\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(tmp_path))\\n\\n        with (\\n            patch(\\\"lfx.cli.commands.build_registry_from_paths\\\", new=AsyncMock(side_effect=KeyboardInterrupt)),\\n            pytest.raises(KeyboardInterrupt),\\n        ):\\n            self._build(flow_json=\\\"{}\\\")\\n\\n        assert list(tmp_path.iterdir()) == []\\n\\n    def test_inline_flow_keeps_temp_file_for_caller_on_success(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"The success path must still hand the path to ``serve_command``'s finally.\\\"\\\"\\\"\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(tmp_path))\\n\\n        with patch(\\\"lfx.cli.commands.build_registry_from_paths\\\", new=AsyncMock(return_value=MagicMock())):\\n            _registry, temp_file = self._build(flow_json=\\\"{}\\\")\\n\\n        assert temp_file is not None\\n        assert Path(temp_file).exists()\\n        assert [entry.name for entry in tmp_path.iterdir()] == [Path(temp_file).name]\\n\\n    def test_upgraded_file_removes_temp_file_when_registry_build_fails(self, tmp_path, monkeypatch):\\n        import typer\\n\\n        source_path = tmp_path / \\\"flow.json\\\"\\n        source_path.write_text(\\\"{}\\\")\\n        temp_dir = tmp_path / \\\"temp\\\"\\n        temp_dir.mkdir()\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(temp_dir))\\n\\n        with (\\n            patch(\\\"lfx.cli.commands._gate_flow_for_serve\\\", return_value={}),\\n            patch(\\\"lfx.cli.commands.build_registry_from_paths\\\", new=AsyncMock(side_effect=ValueError(\\\"invalid flow\\\"))),\\n            pytest.raises(typer.Exit),\\n        ):\\n            self._build(script_paths=[str(source_path)], upgrade_flow=\\\"safe\\\")\\n\\n        assert list(temp_dir.iterdir()) == []\\n\\n\\nclass TestServeCommandMultiFlow:\\n    def test_serve_command_with_directory(self, tmp_path):\\n        from lfx.cli.commands import serve_command\\n\\n        flow_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        (tmp_path / \\\"flow1.json\\\").write_text(json.dumps(flow_data))\\n        (tmp_path / \\\"flow2.json\\\").write_text(json.dumps(flow_data))\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.flow_id = None\\n        mock_graph.nodes = {}\\n        mock_graph.edges = []\\n\\n        with (\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n            patch(\\\"lfx.cli.commands.uvicorn.run\\\"),\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        ):\\n            import typer\\n            from typer.testing import CliRunner\\n\\n            app = typer.Typer()\\n            app.command()(serve_command)\\n            runner = CliRunner()\\n            result = runner.invoke(app, [str(tmp_path)])\\n\\n        assert result.exit_code == 0, result.output\\n\\n    def test_serve_command_with_multiple_files(self, tmp_path):\\n        from lfx.cli.commands import serve_command\\n\\n        flow_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        p1 = tmp_path / \\\"flow1.json\\\"\\n        p2 = tmp_path / \\\"flow2.json\\\"\\n        p1.write_text(json.dumps(flow_data))\\n        p2.write_text(json.dumps(flow_data))\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.flow_id = None\\n        mock_graph.nodes = {}\\n        mock_graph.edges = []\\n\\n        with (\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n            patch(\\\"lfx.cli.commands.uvicorn.run\\\"),\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        ):\\n            import typer\\n            from typer.testing import CliRunner\\n\\n            app = typer.Typer()\\n            app.command()(serve_command)\\n            runner = CliRunner()\\n            result = runner.invoke(app, [str(p1), str(p2)])\\n\\n        assert result.exit_code == 0, result.output\\n\\n    def test_serve_command_empty_directory_exits_nonzero(self, tmp_path):\\n        from lfx.cli.commands import serve_command\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}):  # pragma: allowlist secret\\n            import typer\\n            from typer.testing import CliRunner\\n\\n            app = typer.Typer()\\n            app.command()(serve_command)\\n            runner = CliRunner()\\n            result = runner.invoke(app, [str(tmp_path)])\\n\\n        assert result.exit_code != 0\\n\\n\\nclass TestPythonScriptServe:\\n    def test_load_graph_and_meta_dispatches_to_script_loader_for_py(self, tmp_path):\\n        \\\"\\\"\\\"_load_graph_and_meta must call load_graph_from_script for .py files, not load_flow_from_json.\\\"\\\"\\\"\\n        import asyncio\\n\\n        from lfx.cli.commands import _load_graph_and_meta\\n\\n        script = tmp_path / \\\"my_flow.py\\\"\\n        script.write_text(\\\"graph = None\\\")\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.flow_id = None\\n\\n        # load_graph_from_script is lazily imported inside _load_graph_and_meta,\\n        # so patch its module-level name directly.\\n        with (\\n            patch(\\\"lfx.cli.commands.load_graph_from_script\\\", new=AsyncMock(return_value=mock_graph)) as mock_script,\\n            patch(\\\"lfx.cli.commands.find_graph_variable\\\", return_value={\\\"source\\\": \\\"x\\\", \\\"type\\\": \\\"Graph\\\", \\\"line\\\": 1}),\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\") as mock_json,\\n        ):\\n            _graph, meta, raw_json = asyncio.run(_load_graph_and_meta(script, tmp_path, check_variables=False))\\n\\n        mock_json.assert_not_called()\\n        mock_script.assert_called_once_with(script)\\n        assert raw_json is None\\n        assert meta.title == \\\"my_flow\\\"\\n        assert meta.relative_path == \\\"my_flow.py\\\"\\n\\n    def test_serve_command_accepts_py_file(self, tmp_path):\\n        \\\"\\\"\\\"Lfx serve my_script.py must not be rejected as an unsupported file type.\\\"\\\"\\\"\\n        from lfx.cli.commands import serve_command\\n\\n        script = tmp_path / \\\"my_flow.py\\\"\\n        script.write_text(\\\"graph = None\\\")\\n\\n        mock_graph = MagicMock()\\n        mock_graph.prepare = MagicMock()\\n        mock_graph.flow_id = None\\n        mock_graph.nodes = {}\\n        mock_graph.edges = []\\n\\n        with (\\n            patch(\\\"lfx.cli.commands.load_graph_from_script\\\", new=AsyncMock(return_value=mock_graph)),\\n            patch(\\\"lfx.cli.commands.find_graph_variable\\\", return_value={\\\"type\\\": \\\"assignment\\\", \\\"line\\\": 1}),\\n            patch(\\\"lfx.cli.commands.uvicorn.run\\\"),\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        ):\\n            import typer\\n            from typer.testing import CliRunner\\n\\n            app = typer.Typer()\\n            app.command()(serve_command)\\n            result = CliRunner().invoke(app, [str(script)])\\n\\n        assert result.exit_code == 0, result.output\\n\\n    def test_serve_command_rejects_unsupported_extension(self, tmp_path):\\n        \\\"\\\"\\\"Non-.json/.py files must exit with an error.\\\"\\\"\\\"\\n        from lfx.cli.commands import serve_command\\n\\n        bad = tmp_path / \\\"flow.txt\\\"\\n        bad.write_text(\\\"not a flow\\\")\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}):  # pragma: allowlist secret\\n            import typer\\n            from typer.testing import CliRunner\\n\\n            app = typer.Typer()\\n            app.command()(serve_command)\\n            result = CliRunner().invoke(app, [str(bad)])\\n\\n        assert result.exit_code != 0\\n        assert \\\".json or .py\\\" in result.output\\n\\n\\ndef test_build_registry_from_paths_no_env_fallback_stamps_graphs(tmp_path):\\n    \\\"\\\"\\\"build_registry_from_paths with no_env_fallback=True must stamp each graph's context.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from lfx.cli.commands import build_registry_from_paths\\n\\n    p = tmp_path / \\\"flow.json\\\"\\n    p.write_text(json.dumps({\\\"nodes\\\": [], \\\"edges\\\": []}))\\n\\n    mock_graph = MagicMock()\\n    mock_graph.prepare = MagicMock()\\n    mock_graph.flow_id = None\\n    mock_graph.context = {}\\n\\n    with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n        registry = asyncio.run(\\n            build_registry_from_paths([p], lambda _: None, check_variables=False, no_env_fallback=True)\\n        )\\n    flow_id = registry.list_metas()[0].id\\n    graph, _ = registry.get(flow_id)\\n    assert graph.context.get(\\\"no_env_fallback\\\") is True\\n\\n\\ndef test_build_registry_from_paths_default_does_not_stamp(tmp_path):\\n    \\\"\\\"\\\"build_registry_from_paths without no_env_fallback must not stamp the context.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from lfx.cli.commands import build_registry_from_paths\\n\\n    p = tmp_path / \\\"flow.json\\\"\\n    p.write_text(json.dumps({\\\"nodes\\\": [], \\\"edges\\\": []}))\\n\\n    mock_graph = MagicMock()\\n    mock_graph.prepare = MagicMock()\\n    mock_graph.flow_id = None\\n    mock_graph.context = {}\\n\\n    with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n        registry = asyncio.run(build_registry_from_paths([p], lambda _: None, check_variables=False))\\n    flow_id = registry.list_metas()[0].id\\n    graph, _ = registry.get(flow_id)\\n    assert not graph.context.get(\\\"no_env_fallback\\\")\\n\\n\\ndef test_build_registry_from_directory_no_env_fallback_stamps_graphs(tmp_path):\\n    \\\"\\\"\\\"build_registry_from_directory with no_env_fallback=True must stamp each graph's context.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from lfx.cli.commands import build_registry_from_directory\\n\\n    p = tmp_path / \\\"flow.json\\\"\\n    p.write_text(json.dumps({\\\"nodes\\\": [], \\\"edges\\\": []}))\\n\\n    mock_graph = MagicMock()\\n    mock_graph.prepare = MagicMock()\\n    mock_graph.flow_id = None\\n    mock_graph.context = {}\\n\\n    with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n        registry = asyncio.run(\\n            build_registry_from_directory(tmp_path, lambda _: None, check_variables=False, no_env_fallback=True)\\n        )\\n    flow_id = registry.list_metas()[0].id\\n    graph, _ = registry.get(flow_id)\\n    assert graph.context.get(\\\"no_env_fallback\\\") is True\\n\\n\\ndef test_build_registry_from_directory_default_does_not_stamp(tmp_path):\\n    \\\"\\\"\\\"build_registry_from_directory without no_env_fallback must not stamp the context.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from lfx.cli.commands import build_registry_from_directory\\n\\n    p = tmp_path / \\\"flow.json\\\"\\n    p.write_text(json.dumps({\\\"nodes\\\": [], \\\"edges\\\": []}))\\n\\n    mock_graph = MagicMock()\\n    mock_graph.prepare = MagicMock()\\n    mock_graph.flow_id = None\\n    mock_graph.context = {}\\n\\n    with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n        registry = asyncio.run(build_registry_from_directory(tmp_path, lambda _: None, check_variables=False))\\n    flow_id = registry.list_metas()[0].id\\n    graph, _ = registry.get(flow_id)\\n    assert not graph.context.get(\\\"no_env_fallback\\\")\\n\\n\\ndef test_build_registry_from_paths_passes_raw_json_to_store():\\n    \\\"\\\"\\\"build_registry_from_paths must pass raw_json so JSON flows are written to the store.\\\"\\\"\\\"\\n    import asyncio\\n    import json\\n    import tempfile\\n    from pathlib import Path\\n    from unittest.mock import MagicMock, patch\\n\\n    from lfx.cli.commands import build_registry_from_paths\\n    from lfx.cli.flow_store import NullFlowStore\\n\\n    written = {}\\n\\n    class SpyStore(NullFlowStore):\\n        def write(self, flow_id, flow_json):\\n            written[flow_id] = flow_json\\n\\n    flow_data = {\\\"name\\\": \\\"Test\\\", \\\"description\\\": \\\"\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    with tempfile.TemporaryDirectory() as tmp:\\n        p = Path(tmp) / \\\"flow.json\\\"\\n        p.write_text(json.dumps(flow_data))\\n        with patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph):\\n            registry = asyncio.run(\\n                build_registry_from_paths([p], lambda _: None, check_variables=False, store=SpyStore())\\n            )\\n\\n    assert len(written) == 1\\n    flow_id = registry.list_metas()[0].id\\n    assert written[flow_id][\\\"name\\\"] == \\\"Test\\\"\\n\\n\\ndef test_build_registry_from_paths_py_file_skips_store():\\n    \\\"\\\"\\\".py flows must not write to the store (no raw JSON round-trip).\\\"\\\"\\\"\\n    import asyncio\\n    import tempfile\\n    from pathlib import Path\\n    from unittest.mock import AsyncMock, MagicMock, patch\\n\\n    from lfx.cli.commands import build_registry_from_paths\\n    from lfx.cli.flow_store import NullFlowStore\\n\\n    written = {}\\n\\n    class SpyStore(NullFlowStore):\\n        def write(self, flow_id, flow_json):\\n            written[flow_id] = flow_json\\n\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    with tempfile.TemporaryDirectory() as tmp:\\n        p = Path(tmp) / \\\"flow.py\\\"\\n        p.write_text(\\\"graph = None\\\\n\\\")\\n        with (\\n            patch(\\\"lfx.cli.commands.load_graph_from_script\\\", new=AsyncMock(return_value=mock_graph)),\\n            patch(\\\"lfx.cli.commands.find_graph_variable\\\", return_value={\\\"source\\\": \\\"x\\\", \\\"type\\\": \\\"Graph\\\", \\\"line\\\": 1}),\\n        ):\\n            asyncio.run(build_registry_from_paths([p], lambda _: None, check_variables=False, store=SpyStore()))\\n\\n    assert written == {}\\n\\n\\ndef test_startup_scan_store_flows_accessible_lazily(tmp_path):\\n    \\\"\\\"\\\"build_registry_from_paths() does NOT call warm_from_store() \u2014 that is serve_command's job.\\n\\n    Pre-existing store flows are NOT eagerly loaded by the builder but are counted\\n    via list_metas() and accessible on first get().  serve_command adds the\\n    warm_from_store() call for single-worker mode after build_registry_from_paths returns.\\n    \\\"\\\"\\\"\\n    import asyncio\\n    from unittest.mock import MagicMock, patch\\n\\n    from lfx.cli.commands import build_registry_from_paths\\n    from lfx.cli.flow_store import FilesystemFlowStore\\n\\n    store = FilesystemFlowStore(tmp_path)\\n    raw = {\\\"name\\\": \\\"Pre-existing\\\", \\\"description\\\": None, \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"id\\\": \\\"pre-existing-id\\\"}\\n    store.write(\\\"pre-existing-id\\\", raw)\\n\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n        registry = asyncio.run(build_registry_from_paths([], lambda _: None, check_variables=False, store=store))\\n\\n    # Builder does NOT eagerly pre-warm \u2014 that's serve_command's responsibility\\n    assert \\\"pre-existing-id\\\" not in registry._flows\\n\\n    # Counted by len() / list_metas() even before warm_from_store() is called\\n    assert len(registry) == 1\\n\\n    # Accessible via get() which triggers lazy load (simulating serve_command's warm_from_store)\\n    with patch(\\\"lfx.cli.serve_app.load_flow_from_json\\\", return_value=mock_graph):\\n        result = registry.get(\\\"pre-existing-id\\\")\\n    assert result is not None\\n    assert result[1].title == \\\"Pre-existing\\\"\\n\\n\\ndef _make_fake_gunicorn_app(*, captured=None, captured_env=None):\\n    \\\"\\\"\\\"Stand-in for ``LFXGunicornApp`` that records launch args/env instead of forking workers.\\n\\n    ``captured`` (when given) receives ``app_import_string`` and ``options`` (the gunicorn\\n    config); ``captured_env`` (when given) receives a snapshot of ``os.environ`` taken inside\\n    ``run()`` \u2014 i.e. what forked workers would inherit. Either may be omitted when the test\\n    doesn't need it.\\n    \\\"\\\"\\\"\\n\\n    class FakeGunicornApp:\\n        def __init__(self, app_import_string=None, options=None):\\n            if captured is not None:\\n                captured[\\\"app_import_string\\\"] = app_import_string\\n                captured[\\\"options\\\"] = options\\n\\n        def run(self):\\n            if captured_env is not None:\\n                captured_env.update(os.environ)\\n\\n    return FakeGunicornApp\\n\\n\\ndef _run_serve_capturing_gunicorn(*, workers, max_requests, captured, sync_workers=False):\\n    \\\"\\\"\\\"Run serve_command under a stubbed gunicorn launcher, capturing options + launch env.\\\"\\\"\\\"\\n    import json\\n    import os\\n    import tempfile\\n    from pathlib import Path\\n    from unittest.mock import MagicMock, patch\\n\\n    from lfx.cli.commands import serve_command\\n\\n    flow_data = {\\\"name\\\": \\\"Test\\\", \\\"description\\\": \\\"\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    with tempfile.TemporaryDirectory() as tmp:\\n        p = Path(tmp) / \\\"flow.json\\\"\\n        p.write_text(json.dumps(flow_data))\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n            patch(\\\"lfx.cli.serve_gunicorn.LFXGunicornApp\\\", _make_fake_gunicorn_app(captured=captured)),\\n        ):\\n            # Direct call (not via CLI): typer defaults are not applied, so pass\\n            # max_requests / reset_environ / sync_workers explicitly even when None/False\\n            # (OptionInfo sentinels are truthy).\\n            serve_command(\\n                script_paths=[str(p)],\\n                host=\\\"127.0.0.1\\\",\\n                port=9999,\\n                workers=workers,\\n                verbose=False,\\n                env_file=None,\\n                log_level=\\\"warning\\\",\\n                flow_json=None,\\n                flow_dir=None,\\n                stdin=False,\\n                check_variables=False,\\n                no_env_fallback=False,\\n                max_requests=max_requests,\\n                reset_environ=False,\\n                sync_workers=sync_workers,\\n            )\\n\\n\\ndef test_serve_command_passes_workers_to_gunicorn():\\n    \\\"\\\"\\\"--workers N is forwarded to gunicorn; default --max-requests recycles periodically.\\n\\n    Multi-worker serving runs gunicorn with preload; the app is loaded by the\\n    preload master via the ``serve_preloaded_app`` import string. With no\\n    --max-requests, max_requests defaults to DEFAULT_MAX_REQUESTS so warm workers\\n    recycle periodically to shed memory (with 10% jitter).\\n    \\\"\\\"\\\"\\n    from lfx.cli.commands import DEFAULT_MAX_REQUESTS\\n\\n    captured: dict = {}\\n    _run_serve_capturing_gunicorn(workers=4, max_requests=None, captured=captured)\\n\\n    assert captured[\\\"options\\\"][\\\"workers\\\"] == 4\\n    # The preload master loads the warm app from this import string, not a factory.\\n    assert captured[\\\"app_import_string\\\"] == \\\"lfx.cli.serve_preloaded_app:app\\\"\\n    assert captured[\\\"options\\\"][\\\"preload_app\\\"] is True\\n    # Default: periodic recycling to bound memory (not 0/never).\\n    assert captured[\\\"options\\\"][\\\"max_requests\\\"] == DEFAULT_MAX_REQUESTS\\n    assert captured[\\\"options\\\"][\\\"max_requests_jitter\\\"] == DEFAULT_MAX_REQUESTS // 10\\n    # Our named async worker class is used, not the stock one.\\n    assert captured[\\\"options\\\"][\\\"worker_class\\\"] == \\\"lfx.cli.serve_gunicorn.LFXUvicornWorker\\\"\\n\\n\\ndef test_serve_command_max_requests_propagates_to_gunicorn():\\n    \\\"\\\"\\\"--max-requests N is forwarded to gunicorn as max_requests (overrides the default).\\\"\\\"\\\"\\n    captured: dict = {}\\n    _run_serve_capturing_gunicorn(workers=4, max_requests=1, captured=captured)\\n\\n    assert captured[\\\"options\\\"][\\\"max_requests\\\"] == 1\\n    # 1 // 10 == 0: small explicit values get no jitter.\\n    assert captured[\\\"options\\\"][\\\"max_requests_jitter\\\"] == 0\\n    assert captured[\\\"options\\\"][\\\"preload_app\\\"] is True\\n\\n\\ndef test_serve_command_max_requests_zero_disables_recycling():\\n    \\\"\\\"\\\"--max-requests 0 explicitly disables recycling, overriding the periodic default.\\\"\\\"\\\"\\n    captured: dict = {}\\n    _run_serve_capturing_gunicorn(workers=4, max_requests=0, captured=captured)\\n\\n    assert captured[\\\"options\\\"][\\\"max_requests\\\"] == 0\\n    assert captured[\\\"options\\\"][\\\"max_requests_jitter\\\"] == 0\\n\\n\\ndef test_serve_command_sets_startup_paths_env_for_multi_worker(tmp_path):\\n    \\\"\\\"\\\"serve_command must set LFX_SERVE_STARTUP_PATHS so each worker can reload flows.\\\"\\\"\\\"\\n    import json\\n    import os\\n    from unittest.mock import MagicMock, patch\\n\\n    from lfx.cli.commands import serve_command\\n    from lfx.cli.serve_app import _SERVE_STARTUP_PATHS_ENV\\n\\n    flow_data = {\\\"name\\\": \\\"Test\\\", \\\"description\\\": \\\"\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    captured_env: dict = {}\\n\\n    p = tmp_path / \\\"flow.json\\\"\\n    p.write_text(json.dumps(flow_data))\\n\\n    with (\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n        patch(\\\"lfx.cli.serve_gunicorn.LFXGunicornApp\\\", _make_fake_gunicorn_app(captured_env=captured_env)),\\n    ):\\n        serve_command(\\n            script_paths=[str(p)],\\n            host=\\\"127.0.0.1\\\",\\n            port=9999,\\n            workers=2,\\n            verbose=False,\\n            env_file=None,\\n            log_level=\\\"warning\\\",\\n            flow_json=None,\\n            flow_dir=None,\\n            stdin=False,\\n            check_variables=False,\\n            no_env_fallback=False,\\n            reset_environ=False,\\n            sync_workers=False,\\n        )\\n\\n    assert _SERVE_STARTUP_PATHS_ENV in captured_env, \\\"LFX_SERVE_STARTUP_PATHS must be set before the launch\\\"\\n    paths = json.loads(captured_env[_SERVE_STARTUP_PATHS_ENV])\\n    assert len(paths) == 1\\n    assert paths[0].endswith(\\\"flow.json\\\"), f\\\"expected flow.json in paths, got {paths}\\\"\\n    # Must be cleaned up after uvicorn exits\\n    assert _SERVE_STARTUP_PATHS_ENV not in os.environ, \\\"LFX_SERVE_STARTUP_PATHS must be cleaned up after server exits\\\"\\n\\n\\ndef test_serve_command_does_not_set_startup_paths_when_flow_dir_set(tmp_path):\\n    \\\"\\\"\\\"When --flow-dir is set, LFX_SERVE_STARTUP_PATHS must be empty.\\n\\n    Workers load startup flows via warm_from_store() (parent persisted them to\\n    the store).  Sending file paths would cause each worker to re-load and re-write\\n    them redundantly, and would break the .py restriction logic.\\n    \\\"\\\"\\\"\\n    import json\\n    import os\\n    from unittest.mock import MagicMock, patch\\n\\n    from lfx.cli.commands import serve_command\\n    from lfx.cli.serve_app import _SERVE_STARTUP_PATHS_ENV\\n\\n    flow_data = {\\\"name\\\": \\\"Test\\\", \\\"description\\\": \\\"\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    captured_env: dict = {}\\n\\n    p = tmp_path / \\\"flow.json\\\"\\n    p.write_text(json.dumps(flow_data))\\n\\n    with (\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n        patch(\\\"lfx.cli.serve_gunicorn.LFXGunicornApp\\\", _make_fake_gunicorn_app(captured_env=captured_env)),\\n    ):\\n        serve_command(\\n            script_paths=[str(p)],\\n            host=\\\"127.0.0.1\\\",\\n            port=9999,\\n            workers=2,\\n            verbose=False,\\n            env_file=None,\\n            log_level=\\\"warning\\\",\\n            flow_json=None,\\n            flow_dir=tmp_path / \\\"store\\\",  # flow_dir is set\\n            stdin=False,\\n            check_variables=False,\\n            no_env_fallback=False,\\n            reset_environ=False,\\n            sync_workers=False,\\n        )\\n\\n    assert _SERVE_STARTUP_PATHS_ENV in captured_env, \\\"env var must still be set (to empty list)\\\"\\n    paths = json.loads(captured_env[_SERVE_STARTUP_PATHS_ENV])\\n    assert paths == [], f\\\"startup paths must be empty when flow_dir is set, got {paths}\\\"\\n\\n\\ndef test_serve_command_warns_when_workers_gt1_without_flow_dir():\\n    \\\"\\\"\\\"--workers > 1 without --flow-dir should emit a warning to stderr.\\\"\\\"\\\"\\n    import json\\n    import os\\n    import tempfile\\n    from pathlib import Path\\n    from unittest.mock import MagicMock, patch\\n\\n    from lfx.cli.commands import serve_command\\n\\n    flow_data = {\\\"name\\\": \\\"Test\\\", \\\"description\\\": \\\"\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    stderr_output = []\\n\\n    with tempfile.TemporaryDirectory() as tmp:\\n        p = Path(tmp) / \\\"flow.json\\\"\\n        p.write_text(json.dumps(flow_data))\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n            patch(\\\"lfx.cli.serve_gunicorn.LFXGunicornApp\\\", _make_fake_gunicorn_app()),\\n            patch(\\\"typer.echo\\\", side_effect=lambda msg, **kw: stderr_output.append(msg) if kw.get(\\\"err\\\") else None),\\n        ):\\n            serve_command(\\n                script_paths=[str(p)],\\n                host=\\\"127.0.0.1\\\",\\n                port=9999,\\n                workers=2,\\n                verbose=False,\\n                env_file=None,\\n                log_level=\\\"warning\\\",\\n                flow_json=None,\\n                flow_dir=None,\\n                stdin=False,\\n                check_variables=False,\\n                no_env_fallback=False,\\n                reset_environ=False,\\n                sync_workers=False,\\n            )\\n\\n    assert any(\\\"--flow-dir\\\" in msg for msg in stderr_output), (\\n        f\\\"Expected a warning mentioning --flow-dir, got: {stderr_output}\\\"\\n    )\\n\\n\\ndef test_serve_command_rejects_py_with_multiple_workers(tmp_path):\\n    \\\"\\\"\\\".py startup files must be rejected when --workers > 1 (cannot persist to store).\\\"\\\"\\\"\\n    import os\\n    from unittest.mock import patch\\n\\n    from lfx.cli.commands import serve_command\\n\\n    script = tmp_path / \\\"my_flow.py\\\"\\n    script.write_text(\\\"graph = None\\\")\\n\\n    stderr_output = []\\n\\n    with (\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\"),\\n        patch(\\\"typer.echo\\\", side_effect=lambda msg, **kw: stderr_output.append(msg) if kw.get(\\\"err\\\") else None),\\n    ):\\n        from click.exceptions import Exit as ClickExit\\n\\n        with pytest.raises(ClickExit):\\n            serve_command(\\n                script_paths=[str(script)],\\n                host=\\\"127.0.0.1\\\",\\n                port=9999,\\n                workers=2,\\n                verbose=False,\\n                env_file=None,\\n                log_level=\\\"warning\\\",\\n                flow_json=None,\\n                flow_dir=tmp_path / \\\"flows\\\",\\n                stdin=False,\\n                check_variables=False,\\n                no_env_fallback=False,\\n                reset_environ=False,\\n                sync_workers=False,\\n            )\\n\\n    assert any(\\\".py\\\" in msg and \\\"cannot be used\\\" in msg for msg in stderr_output), stderr_output\\n\\n\\ndef test_serve_command_allows_py_with_multiple_workers_no_flow_dir(tmp_path):\\n    \\\"\\\"\\\".py files + --workers > 1 + no --flow-dir must be allowed.\\n\\n    Each worker reloads the .py via LFX_SERVE_STARTUP_PATHS since there is no\\n    store.  The error only applies when --flow-dir is set (workers would skip\\n    startup paths and warm_from_store, missing the .py flow entirely).\\n    \\\"\\\"\\\"\\n    import json\\n    import os\\n    from unittest.mock import AsyncMock, MagicMock, patch\\n\\n    from lfx.cli.commands import serve_command\\n    from lfx.cli.serve_app import _SERVE_STARTUP_PATHS_ENV\\n\\n    script = tmp_path / \\\"my_flow.py\\\"\\n    script.write_text(\\\"graph = None\\\")\\n\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n    captured_env: dict = {}\\n\\n    with (\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        patch(\\\"lfx.cli.commands.load_graph_from_script\\\", new=AsyncMock(return_value=mock_graph)),\\n        patch(\\\"lfx.cli.commands.find_graph_variable\\\", return_value={\\\"type\\\": \\\"assignment\\\", \\\"line\\\": 1}),\\n        patch(\\\"lfx.cli.serve_gunicorn.LFXGunicornApp\\\", _make_fake_gunicorn_app(captured_env=captured_env)),\\n    ):\\n        # Must NOT raise \u2014 .py without flow_dir is allowed for multi-worker\\n        serve_command(\\n            script_paths=[str(script)],\\n            host=\\\"127.0.0.1\\\",\\n            port=9999,\\n            workers=2,\\n            verbose=False,\\n            env_file=None,\\n            log_level=\\\"warning\\\",\\n            flow_json=None,\\n            flow_dir=None,  # no flow_dir \u2014 .py is allowed here\\n            stdin=False,\\n            check_variables=False,\\n            no_env_fallback=False,\\n            reset_environ=False,\\n            sync_workers=False,\\n        )\\n\\n    # LFX_SERVE_STARTUP_PATHS must contain the .py path so workers can reload it\\n    assert _SERVE_STARTUP_PATHS_ENV in captured_env, \\\"LFX_SERVE_STARTUP_PATHS must be set\\\"\\n    paths = json.loads(captured_env[_SERVE_STARTUP_PATHS_ENV])\\n    assert any(\\\"my_flow.py\\\" in p for p in paths), f\\\"expected .py path in STARTUP_PATHS, got {paths}\\\"\\n\\n\\ndef test_serve_command_no_warning_when_workers_gt1_with_flow_dir(tmp_path):\\n    \\\"\\\"\\\"--workers > 1 WITH --flow-dir must not emit the missing-store warning.\\\"\\\"\\\"\\n    import json\\n    import os\\n    import tempfile\\n    from pathlib import Path\\n    from unittest.mock import MagicMock, patch\\n\\n    from lfx.cli.commands import serve_command\\n\\n    flow_data = {\\\"name\\\": \\\"Test\\\", \\\"description\\\": \\\"\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    stderr_output = []\\n\\n    with tempfile.TemporaryDirectory() as tmp:\\n        p = Path(tmp) / \\\"flow.json\\\"\\n        p.write_text(json.dumps(flow_data))\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n            patch(\\\"lfx.cli.serve_gunicorn.LFXGunicornApp\\\", _make_fake_gunicorn_app()),\\n            patch(\\\"typer.echo\\\", side_effect=lambda msg, **kw: stderr_output.append(msg) if kw.get(\\\"err\\\") else None),\\n        ):\\n            serve_command(\\n                script_paths=[str(p)],\\n                host=\\\"127.0.0.1\\\",\\n                port=9999,\\n                workers=2,\\n                verbose=False,\\n                env_file=None,\\n                log_level=\\\"warning\\\",\\n                flow_json=None,\\n                flow_dir=tmp_path / \\\"flows\\\",\\n                stdin=False,\\n                check_variables=False,\\n                no_env_fallback=False,\\n                reset_environ=False,\\n                sync_workers=False,\\n            )\\n\\n    assert not any(\\\"--flow-dir\\\" in msg for msg in stderr_output)\\n\\n\\ndef test_serve_command_warns_when_multiworker_has_no_isolation(tmp_path):\\n    \\\"\\\"\\\"--workers > 1 without an isolation mechanism must warn; --reset-environ silences it.\\\"\\\"\\\"\\n    import json\\n    import tempfile\\n    from pathlib import Path\\n    from unittest.mock import MagicMock, patch\\n\\n    from lfx.cli.commands import serve_command\\n\\n    flow_data = {\\\"name\\\": \\\"Test\\\", \\\"description\\\": \\\"\\\", \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}}\\n    mock_graph = MagicMock()\\n    mock_graph.context = {}\\n\\n    def _run(*, reset_environ):\\n        stderr_output = []\\n        with tempfile.TemporaryDirectory() as tmp:\\n            p = Path(tmp) / \\\"flow.json\\\"\\n            p.write_text(json.dumps(flow_data))\\n            with (\\n                patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n                patch(\\\"lfx.cli.commands.load_flow_from_json\\\", return_value=mock_graph),\\n                patch(\\\"lfx.cli.serve_gunicorn.LFXGunicornApp\\\", _make_fake_gunicorn_app()),\\n                patch(\\\"typer.echo\\\", side_effect=lambda msg, **kw: stderr_output.append(msg) if kw.get(\\\"err\\\") else None),\\n            ):\\n                serve_command(\\n                    script_paths=[str(p)],\\n                    host=\\\"127.0.0.1\\\",\\n                    port=9999,\\n                    workers=2,\\n                    verbose=False,\\n                    env_file=None,\\n                    log_level=\\\"warning\\\",\\n                    flow_json=None,\\n                    flow_dir=tmp_path / \\\"flows\\\",  # avoids the separate missing-store warning\\n                    stdin=False,\\n                    check_variables=False,\\n                    no_env_fallback=False,\\n                    reset_environ=reset_environ,\\n                    sync_workers=False,\\n                )\\n        return stderr_output\\n\\n    # No isolation flag -> warn loudly.\\n    assert any(\\\"per-request isolation\\\" in msg for msg in _run(reset_environ=False))\\n    # --reset-environ provides isolation -> no warning.\\n    assert not any(\\\"per-request isolation\\\" in msg for msg in _run(reset_environ=True))\\n\\n\\n# ---------------------------------------------------------------------------\\n# --upgrade-flow gate parity with `lfx run`\\n#\\n# `serve` and `run` share lfx.upgrade.cli_gate.apply_upgrade_gate; these tests\\n# mirror TestUpgradeFlowOption in tests/unit/run/test_base.py so the two entry\\n# points can't silently diverge. They target the release-1.10.0 registry-based\\n# serve: flows load via lfx.cli.commands.load_flow_from_json (which receives the\\n# parsed temp-file payload) and the server starts via uvicorn.run. The\\n# --upgrade-flow scope here is inline JSON, stdin, and a single .json file.\\n# ---------------------------------------------------------------------------\\n\\n_UPGRADE_REGISTRY_CODE = \\\"class MyComp:\\\\n    pass  # v2\\\"\\n_UPGRADE_NODE_CODE = \\\"class MyComp:\\\\n    pass  # v1\\\"\\n\\n\\ndef _upgrade_registry():\\n    return {\\n        \\\"Cat\\\": {\\n            \\\"MyComp\\\": {\\n                \\\"template\\\": {\\\"code\\\": {\\\"value\\\": _UPGRADE_REGISTRY_CODE}},\\n                \\\"outputs\\\": [{\\\"name\\\": \\\"o\\\", \\\"display_name\\\": \\\"O\\\", \\\"types\\\": [\\\"M\\\"], \\\"method\\\": \\\"m\\\", \\\"allows_loop\\\": False}],\\n                \\\"metadata\\\": {},\\n            }\\n        }\\n    }\\n\\n\\ndef _upgrade_flow_json(code=_UPGRADE_NODE_CODE, type_=\\\"MyComp\\\"):\\n    return json.dumps(\\n        {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"id\\\": \\\"n1\\\",\\n                    \\\"data\\\": {\\n                        \\\"id\\\": \\\"n1\\\",\\n                        \\\"type\\\": type_,\\n                        \\\"node\\\": {\\n                            \\\"display_name\\\": \\\"My Component\\\",\\n                            \\\"template\\\": {\\\"code\\\": {\\\"value\\\": code}},\\n                            \\\"outputs\\\": [\\n                                {\\\"name\\\": \\\"o\\\", \\\"display_name\\\": \\\"O\\\", \\\"types\\\": [\\\"M\\\"], \\\"method\\\": \\\"m\\\", \\\"allows_loop\\\": False}\\n                            ],\\n                        },\\n                    },\\n                }\\n            ],\\n            \\\"edges\\\": [],\\n        }\\n    )\\n\\n\\ndef _upgrade_flow_json_enveloped(code=_UPGRADE_NODE_CODE, type_=\\\"MyComp\\\"):\\n    \\\"\\\"\\\"An exported-flow envelope wrapping the inner graph: {\\\"name\\\", \\\"description\\\", \\\"data\\\": {...}}.\\\"\\\"\\\"\\n    inner = json.loads(_upgrade_flow_json(code=code, type_=type_))\\n    return json.dumps({\\\"name\\\": \\\"My Flow\\\", \\\"description\\\": \\\"the flow\\\", \\\"data\\\": inner})\\n\\n\\ndef _upgrade_serve_app():\\n    import typer\\n    from lfx.cli.commands import serve_command\\n\\n    app = typer.Typer()\\n    app.command()(serve_command)\\n    return app\\n\\n\\ndef _upgrade_capturing_loader(captured: dict):\\n    \\\"\\\"\\\"Side effect for a patched lfx.cli.commands.load_flow_from_json.\\n\\n    The registry builder calls ``load_flow_from_json(raw_json)`` with the parsed temp-file\\n    payload, so capturing the first positional arg records exactly what serve wrote to disk\\n    for the loader (the real loader does ``flow_graph[\\\"data\\\"]``, so the payload must be\\n    enveloped).\\n    \\\"\\\"\\\"\\n\\n    def _side_effect(payload, *_args, **_kwargs):\\n        captured[\\\"payload\\\"] = payload\\n        graph = MagicMock()\\n        graph.prepare = MagicMock()\\n        graph.flow_id = None\\n        graph.nodes = {}\\n        graph.edges = []\\n        return graph\\n\\n    return _side_effect\\n\\n\\ndef test_serve_upgrade_flow_check_aborts_on_incompatible():\\n    \\\"\\\"\\\"`serve --upgrade-flow=check` refuses to serve an outdated flow and never starts uvicorn.\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    with (\\n        patch(\\\"lfx.upgrade.cli_gate._load_bundled_registry\\\", return_value=_upgrade_registry()),\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n    ):\\n        args = [\\\"--flow-json\\\", _upgrade_flow_json(), \\\"--upgrade-flow\\\", \\\"check\\\"]\\n        result = CliRunner().invoke(_upgrade_serve_app(), args)\\n        assert result.exit_code != 0\\n        assert not mock_uvicorn.called\\n\\n\\ndef test_serve_upgrade_flow_safe_blocked_aborts():\\n    \\\"\\\"\\\"`serve --upgrade-flow=safe` aborts when a component is blocked (not in the registry).\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    with (\\n        patch(\\\"lfx.upgrade.cli_gate._load_bundled_registry\\\", return_value={}),\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n    ):\\n        args = [\\\"--flow-json\\\", _upgrade_flow_json(), \\\"--upgrade-flow\\\", \\\"safe\\\"]\\n        result = CliRunner().invoke(_upgrade_serve_app(), args)\\n        assert result.exit_code != 0\\n        assert not mock_uvicorn.called\\n\\n\\ndef test_serve_upgrade_flow_bad_value_rejected():\\n    \\\"\\\"\\\"An unrecognized --upgrade-flow value is rejected before serving.\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    with (\\n        patch(\\\"lfx.upgrade.cli_gate._load_bundled_registry\\\", return_value=_upgrade_registry()),\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n    ):\\n        args = [\\\"--flow-json\\\", _upgrade_flow_json(), \\\"--upgrade-flow\\\", \\\"typo\\\"]\\n        result = CliRunner().invoke(_upgrade_serve_app(), args)\\n        assert result.exit_code != 0\\n        assert not mock_uvicorn.called\\n\\n\\ndef test_serve_upgrade_flow_safe_proceeds_to_serve():\\n    \\\"\\\"\\\"`serve --upgrade-flow=safe` applies safe upgrades and proceeds to start the server.\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    captured: dict = {}\\n    with (\\n        patch(\\\"lfx.upgrade.cli_gate._load_bundled_registry\\\", return_value=_upgrade_registry()),\\n        patch(\\\"lfx.cli.commands.load_flow_from_json\\\", side_effect=_upgrade_capturing_loader(captured)),\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n    ):\\n        args = [\\\"--flow-json\\\", _upgrade_flow_json(), \\\"--upgrade-flow\\\", \\\"safe\\\"]\\n        result = CliRunner().invoke(_upgrade_serve_app(), args)\\n        assert result.exit_code == 0, result.stdout\\n        assert mock_uvicorn.called\\n\\n    # Bare inline graph gets wrapped by the gate so the loader can read flow_graph[\\\"data\\\"],\\n    # and the node's v1 code was upgraded to the registry's v2 code.\\n    payload = captured[\\\"payload\\\"]\\n    assert \\\"data\\\" in payload, payload\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == _UPGRADE_REGISTRY_CODE\\n\\n\\ndef test_serve_upgrade_safe_inline_envelope_preserved_and_upgraded():\\n    \\\"\\\"\\\"`serve --flow-json <enveloped> --upgrade-flow=safe` keeps outer metadata and upgrades the inner graph.\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    captured: dict = {}\\n    with (\\n        patch(\\\"lfx.upgrade.cli_gate._load_bundled_registry\\\", return_value=_upgrade_registry()),\\n        patch(\\\"lfx.cli.commands.load_flow_from_json\\\", side_effect=_upgrade_capturing_loader(captured)),\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n    ):\\n        args = [\\\"--flow-json\\\", _upgrade_flow_json_enveloped(), \\\"--upgrade-flow\\\", \\\"safe\\\"]\\n        result = CliRunner().invoke(_upgrade_serve_app(), args)\\n        assert result.exit_code == 0, result.stdout\\n        assert mock_uvicorn.called\\n\\n    payload = captured[\\\"payload\\\"]\\n    assert payload[\\\"name\\\"] == \\\"My Flow\\\"  # outer metadata preserved through the upgrade\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == _UPGRADE_REGISTRY_CODE\\n\\n\\ndef test_serve_upgrade_safe_stdin_envelope_preserved():\\n    \\\"\\\"\\\"`serve --stdin <enveloped> --upgrade-flow=safe` keeps outer metadata and writes a loadable payload.\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    captured: dict = {}\\n    with (\\n        patch(\\\"lfx.upgrade.cli_gate._load_bundled_registry\\\", return_value=_upgrade_registry()),\\n        patch(\\\"lfx.cli.commands.load_flow_from_json\\\", side_effect=_upgrade_capturing_loader(captured)),\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n    ):\\n        result = CliRunner().invoke(\\n            _upgrade_serve_app(), [\\\"--stdin\\\", \\\"--upgrade-flow\\\", \\\"safe\\\"], input=_upgrade_flow_json_enveloped()\\n        )\\n        assert result.exit_code == 0, result.stdout\\n        assert mock_uvicorn.called\\n\\n    payload = captured[\\\"payload\\\"]\\n    assert \\\"data\\\" in payload, payload\\n    assert \\\"nodes\\\" in payload[\\\"data\\\"], payload\\n    assert payload[\\\"name\\\"] == \\\"My Flow\\\"\\n\\n\\ndef test_serve_file_upgrade_safe_writes_enveloped_payload():\\n    \\\"\\\"\\\"`serve <file.json> --upgrade-flow=safe` unwraps the file, upgrades, and feeds a loadable payload.\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    envelope = json.loads(_upgrade_flow_json_enveloped())\\n    with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".json\\\", delete=False) as f:\\n        json.dump(envelope, f)\\n        flow_path = f.name\\n\\n    captured: dict = {}\\n    try:\\n        with (\\n            patch(\\\"lfx.upgrade.cli_gate._load_bundled_registry\\\", return_value=_upgrade_registry()),\\n            patch(\\\"lfx.cli.commands.load_flow_from_json\\\", side_effect=_upgrade_capturing_loader(captured)),\\n            patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        ):\\n            result = CliRunner().invoke(_upgrade_serve_app(), [flow_path, \\\"--upgrade-flow\\\", \\\"safe\\\"])\\n            assert result.exit_code == 0, result.stdout\\n            assert mock_uvicorn.called\\n    finally:\\n        Path(flow_path).unlink(missing_ok=True)\\n\\n    payload = captured[\\\"payload\\\"]\\n    assert payload[\\\"name\\\"] == \\\"My Flow\\\"  # outer metadata preserved\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == _UPGRADE_REGISTRY_CODE\\n\\n\\ndef test_serve_file_upgrade_rejects_py_script():\\n    \\\"\\\"\\\"`serve <file.py> --upgrade-flow=...` is rejected \u2014 only JSON flows can be upgrade-checked.\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as f:\\n        f.write(\\\"graph = None\\\\n\\\")\\n        py_path = f.name\\n\\n    try:\\n        with (\\n            patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        ):\\n            result = CliRunner().invoke(_upgrade_serve_app(), [py_path, \\\"--upgrade-flow\\\", \\\"check\\\"])\\n            assert result.exit_code != 0\\n            assert not mock_uvicorn.called\\n    finally:\\n        Path(py_path).unlink(missing_ok=True)\\n\\n\\ndef test_serve_upgrade_rejects_multiple_paths():\\n    \\\"\\\"\\\"`--upgrade-flow` with more than one path is rejected (single .json only).\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    paths = []\\n    try:\\n        for _ in range(2):\\n            with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".json\\\", delete=False) as f:\\n                json.dump(json.loads(_upgrade_flow_json_enveloped()), f)\\n                paths.append(f.name)\\n        with (\\n            patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n            patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n        ):\\n            result = CliRunner().invoke(_upgrade_serve_app(), [*paths, \\\"--upgrade-flow\\\", \\\"safe\\\"])\\n            assert result.exit_code != 0\\n            assert not mock_uvicorn.called\\n    finally:\\n        for p in paths:\\n            Path(p).unlink(missing_ok=True)\\n\\n\\ndef test_serve_upgrade_requires_a_flow_source():\\n    \\\"\\\"\\\"`--upgrade-flow` with no flow source (no paths, --flow-json, or --stdin) is rejected.\\\"\\\"\\\"\\n    from typer.testing import CliRunner\\n\\n    with (\\n        patch(\\\"lfx.cli.commands.uvicorn.run\\\") as mock_uvicorn,\\n        patch.dict(os.environ, {\\\"LANGFLOW_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n    ):\\n        result = CliRunner().invoke(_upgrade_serve_app(), [\\\"--upgrade-flow\\\", \\\"check\\\"])\\n        assert result.exit_code != 0\\n        assert not mock_uvicorn.called\\n\"}]}";
